def check_exists(paths: list[Path]) -> None:
    missing = [path for path in paths if not path.exists()]
    if missing:
        for path in missing:
            print(f"missing: {rel(path)}")
        raise SystemExit(1)
    print(f"exists: {len(paths)} files")


def check_ascii(paths: list[Path]) -> None:
    bad: list[Path] = []
    for path in paths:
        try:
            path.read_text(encoding="ascii")
        except UnicodeDecodeError:
            bad.append(path)
    if bad:
        for path in bad:
            print(f"non-ascii: {rel(path)}")
        raise SystemExit(1)
    print(f"ascii: {len(paths)} files")


def parse_source(source: str, label: str):
    try:
        return Parser.from_source(source)
    except Exception as exc:
        print(f"parse failed: {label}")
        print(exc)
        raise SystemExit(1) from exc


def check_individual_parse(paths: list[Path]) -> None:
    for index, path in enumerate(paths):
        parse_source(read_text(path), rel(path))
        if (index + 1) % 16 == 0:
            check_runner_retained_memory()
    check_runner_retained_memory()
    print(f"parse individual: {len(paths)} files")


def flattened_crates() -> str:
    out: list[str] = []
    for path in crate_paths():
        out.append(f"-- flattened from {rel(path)}\n")
        out.append(read_text(path))
        out.append("\n")
    return "\n".join(out)


def check_flattened_crates() -> str:
    source = flattened_crates()
    program = parse_source(source, "flattened V4 crates")
    diagnostics = TypeChecker().check(program)
    if diagnostics:
        print("typecheck failed: flattened V4 crates")
        for diag in diagnostics[:80]:
            print(diag)
        if len(diagnostics) > 80:
            print(f"... {len(diagnostics) - 80} more diagnostics")
        raise SystemExit(1)
    print(f"flattened crates: statements={len(program.statements)}")
    del diagnostics
    del program
    check_runner_retained_memory()
    return source


def fixture_source(base_source: str, fixture: Path) -> str:
    return base_source + "\n\n-- fixture\n" + read_text(fixture)


def transpile_fixture(base_source: str, fixture: Path) -> tuple[str, bool]:
    label = rel(fixture)
    source = fixture_source(base_source, fixture)
    c_source, diagnostics, uses_ui = transpile(source, fixture.with_suffix(".flat.fk"))
    if diagnostics:
        print(f"transpile failed: {label}")
        for diag in diagnostics[:40]:
            print(diag)
        if len(diagnostics) > 40:
            print(f"... {len(diagnostics) - 40} more diagnostics")
        raise SystemExit(1)
    if c_source is None:
        print(f"transpile failed: {label}")
        print("transpile returned no C source")
        raise SystemExit(1)
    return c_source, uses_ui


_TRANSPILE_WORKER_BASE: str | None = None


def _transpile_worker_init(base_source: str) -> None:
    global _TRANSPILE_WORKER_BASE
    _TRANSPILE_WORKER_BASE = base_source


def _transpile_worker(fixture_text: str) -> tuple[str, int, bool, list[str] | None]:
    """Transpile one fixture in a pool worker; return only sizes, never the C."""
    fixture = Path(fixture_text)
    assert _TRANSPILE_WORKER_BASE is not None
    source = fixture_source(_TRANSPILE_WORKER_BASE, fixture)
    c_source, diagnostics, uses_ui = transpile(source, fixture.with_suffix(".flat.fk"))
    if diagnostics:
        return fixture_text, -1, bool(uses_ui), [str(diag) for diag in diagnostics[:40]] + (
            [f"... {len(diagnostics) - 40} more diagnostics"] if len(diagnostics) > 40 else []
        )
    if c_source is None:
        return fixture_text, -1, bool(uses_ui), ["transpile returned no C source"]
    return fixture_text, len(c_source), bool(uses_ui), None


def fixture_transpile_jobs(count: int) -> int:
    raw = os.environ.get("FREAK_V4_TRANSPILE_JOBS", "").strip()
    if raw:
        try:
            requested = int(raw)
        except ValueError:
            raise SystemExit(f"FREAK_V4_TRANSPILE_JOBS must be an integer, got {raw!r}")
        if requested < 1:
            raise SystemExit("FREAK_V4_TRANSPILE_JOBS must be at least 1")
    else:
        requested = min(os.cpu_count() or 1, 4)
    return max(1, min(requested, count))


def check_fixture_transpile(base_source: str, fixtures: list[Path]) -> None:
    jobs = fixture_transpile_jobs(len(fixtures))
    if jobs <= 1:
        for fixture in fixtures:
            label = rel(fixture)
            c_source, uses_ui = transpile_fixture(base_source, fixture)
            print(f"fixture transpile: {label} c_bytes={len(c_source)} uses_ui={uses_ui}")
            del c_source
            check_runner_retained_memory()
        return

    # Each fixture is an independent whole-program transpile of the flattened
    # crates, so they run in worker processes. Results are reported in fixture
    # order and the first failure (in that order) stops the check, as before.
    from concurrent.futures import ProcessPoolExecutor

    print(f"fixture transpile: {len(fixtures)} fixtures on {jobs} workers")
    with ProcessPoolExecutor(
        max_workers=jobs,
        initializer=_transpile_worker_init,
        initargs=(base_source,),
    ) as pool:
        results = pool.map(_transpile_worker, [str(fixture) for fixture in fixtures])
        for fixture_text, c_bytes, uses_ui, failure in results:
            label = rel(Path(fixture_text))
            if failure is not None:
                print(f"transpile failed: {label}")
                for line in failure:
                    print(line)
                pool.shutdown(wait=False, cancel_futures=True)
                raise SystemExit(1)
            print(f"fixture transpile: {label} c_bytes={c_bytes} uses_ui={uses_ui}")
    check_runner_retained_memory()


class BoundedPipeCapture:
    def __init__(self, limit_bytes: int, tail_bytes: int = 8192) -> None:
        self.limit_bytes = limit_bytes
        self.tail_bytes = tail_bytes
        self.total_bytes = 0
        self.exceeded = False
        self.data = bytearray()
        self.lock = threading.Lock()

    def read_from(self, pipe) -> None:
        try:
            while True:
                chunk = pipe.read(64 * 1024)
                if not chunk:
                    return
                with self.lock:
                    self.total_bytes += len(chunk)
                    self.data.extend(chunk)
                    if self.exceeded or len(self.data) > self.limit_bytes:
                        self.exceeded = True
                        if len(self.data) > self.tail_bytes:
                            del self.data[:-self.tail_bytes]
        finally:
            pipe.close()

    def snapshot(self) -> tuple[int, bool, bytes]:
        with self.lock:
            return self.total_bytes, self.exceeded, bytes(self.data)


class WindowsJob:
    def __init__(self, memory_limit_bytes: int | None) -> None:
        import ctypes
        from ctypes import wintypes

        class JobObjectBasicLimitInformation(ctypes.Structure):
            _fields_ = [
                ("PerProcessUserTimeLimit", ctypes.c_int64),
                ("PerJobUserTimeLimit", ctypes.c_int64),
                ("LimitFlags", wintypes.DWORD),
                ("MinimumWorkingSetSize", ctypes.c_size_t),
                ("MaximumWorkingSetSize", ctypes.c_size_t),
                ("ActiveProcessLimit", wintypes.DWORD),
                ("Affinity", ctypes.c_size_t),
                ("PriorityClass", wintypes.DWORD),
                ("SchedulingClass", wintypes.DWORD),
            ]

        class IoCounters(ctypes.Structure):
            _fields_ = [
                ("ReadOperationCount", ctypes.c_uint64),
                ("WriteOperationCount", ctypes.c_uint64),
                ("OtherOperationCount", ctypes.c_uint64),
                ("ReadTransferCount", ctypes.c_uint64),
                ("WriteTransferCount", ctypes.c_uint64),
                ("OtherTransferCount", ctypes.c_uint64),
            ]

        class JobObjectExtendedLimitInformation(ctypes.Structure):
            _fields_ = [
                ("BasicLimitInformation", JobObjectBasicLimitInformation),
                ("IoInfo", IoCounters),
                ("ProcessMemoryLimit", ctypes.c_size_t),
                ("JobMemoryLimit", ctypes.c_size_t),
                ("PeakProcessMemoryUsed", ctypes.c_size_t),
                ("PeakJobMemoryUsed", ctypes.c_size_t),
            ]

        self.ctypes = ctypes
        self.wintypes = wintypes
        self.info_type = JobObjectExtendedLimitInformation
        self.kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        self.ntdll = ctypes.WinDLL("ntdll")
        self.kernel32.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
        self.kernel32.CreateJobObjectW.restype = wintypes.HANDLE
        self.kernel32.SetInformationJobObject.argtypes = [
            wintypes.HANDLE,
            ctypes.c_int,
            ctypes.c_void_p,
            wintypes.DWORD,
        ]
        self.kernel32.SetInformationJobObject.restype = wintypes.BOOL
        self.kernel32.QueryInformationJobObject.argtypes = [
            wintypes.HANDLE,
            ctypes.c_int,
            ctypes.c_void_p,
            wintypes.DWORD,
            ctypes.c_void_p,
        ]
        self.kernel32.QueryInformationJobObject.restype = wintypes.BOOL
        self.kernel32.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
        self.kernel32.AssignProcessToJobObject.restype = wintypes.BOOL
        self.kernel32.TerminateJobObject.argtypes = [wintypes.HANDLE, wintypes.UINT]
        self.kernel32.TerminateJobObject.restype = wintypes.BOOL
        self.kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        self.kernel32.CloseHandle.restype = wintypes.BOOL
        self.ntdll.NtResumeProcess.argtypes = [wintypes.HANDLE]
        self.ntdll.NtResumeProcess.restype = ctypes.c_long
        self.ntdll.RtlNtStatusToDosError.argtypes = [ctypes.c_long]
        self.ntdll.RtlNtStatusToDosError.restype = wintypes.ULONG

        self.invalid_handle_error: OSError | None = None
        self.handle = self.kernel32.CreateJobObjectW(None, None)
        if not self.handle:
            raise ctypes.WinError(ctypes.get_last_error())

        info = self.info_type()
        info.BasicLimitInformation.LimitFlags = 0x00002000  # KILL_ON_JOB_CLOSE
        if memory_limit_bytes is not None:
            info.BasicLimitInformation.LimitFlags |= 0x00000200  # JOB_MEMORY
            info.JobMemoryLimit = memory_limit_bytes
        if not self.kernel32.SetInformationJobObject(
            self.handle, 9, ctypes.byref(info), ctypes.sizeof(info)
        ):
            error = ctypes.WinError(ctypes.get_last_error())
            self.close()
            raise error

    def assign(self, process: subprocess.Popen[bytes]) -> None:
        self._raise_if_invalid()
        if not self.kernel32.AssignProcessToJobObject(self.handle, process._handle):
            raise self.ctypes.WinError(self.ctypes.get_last_error())

    def resume(self, process: subprocess.Popen[bytes]) -> None:
        status = self.ntdll.NtResumeProcess(process._handle)
        if status != 0:
            error = self.ntdll.RtlNtStatusToDosError(status)
            raise self.ctypes.WinError(error)

    def memory_bytes(self) -> int | None:
        if getattr(self, "invalid_handle_error", None) is not None or not self.handle:
            return None
        info = self.info_type()
        if not self.kernel32.QueryInformationJobObject(
            self.handle, 9, self.ctypes.byref(info), self.ctypes.sizeof(info), None
        ):
            # Optional measurement can fail transiently, but an invalid identity
            # must be retired before cleanup can send its numeric value again.
            code = self.ctypes.get_last_error()
            if code == 6:
                self.handle = None
                self.invalid_handle_error = self.ctypes.WinError(code)
            return None
        return max(int(info.PeakProcessMemoryUsed), int(info.PeakJobMemoryUsed))

    def terminate(self) -> None:
        self._raise_if_invalid()
        if self.handle and not self.kernel32.TerminateJobObject(self.handle, 1):
            self._raise_job_api_error()

    def close(self) -> None:
        self._raise_if_invalid()
        if self.handle:
            if not self.kernel32.CloseHandle(self.handle):
                self._raise_job_api_error()
            self.handle = None

    def _raise_if_invalid(self) -> None:
        error = getattr(self, "invalid_handle_error", None)
        if error is not None:
            # An invalidated identity is not proof of descendant termination
            # or successful resource close. Never send its value to an API again.
            raise error

    def _raise_job_api_error(self) -> None:
        code = self.ctypes.get_last_error()
        error = self.ctypes.WinError(code)
        if code == 6:  # ERROR_INVALID_HANDLE; CRT errno may instead be 9 or 13.
            self.handle = None
            self.invalid_handle_error = error
        raise error


POSIX_PROC_ROOT = Path("/proc")
MEMORY_DIAGNOSTIC_PROCESS_LIMIT = 8


def linux_process_identity(entry: Path) -> tuple[int, int, int] | None:
    """PID, group and start tick authenticate a procfs row across reads."""
    try:
        text = (entry / "stat").read_text(encoding="ascii", errors="replace")
        close_paren = text.rfind(")")
        if close_paren < 0:
            return None
        fields = text[close_paren + 2 :].split()
        if len(fields) < 20:
            return None
        identity = (int(text.split(" ", 1)[0]), int(fields[2]), int(fields[19]))
        return identity if identity[0] == int(entry.name) else None
    except (OSError, ValueError):
        return None


def posix_process_group_memory_bytes(group_id: int, *, sample: dict | None = None) -> int | None:
    proc_root = POSIX_PROC_ROOT
    try:
        if proc_root.exists():
            total_kb = 0
            process_count = 0
            contributors = []
            for entry in proc_root.iterdir():
                if not entry.name.isdigit():
                    continue
                identity = linux_process_identity(entry)
                if identity is None or identity[1] != group_id:
                    continue
                try:
                    status_lines = (entry / "status").read_text(
                        encoding="ascii", errors="replace"
                    ).splitlines()
                except OSError:
                    continue
                memory_kb = {"VmRSS:": 0, "VmSwap:": 0}
                for line in status_lines:
                    fields = line.split()
                    if fields and fields[0] in memory_kb:
                        memory_kb[fields[0]] = int(fields[1])
                # A recycled PID or a group change must not attribute another
                # process's status bytes to the group selected by the first stat.
                if linux_process_identity(entry) != identity:
                    continue
                rss, swap = memory_kb["VmRSS:"], memory_kb["VmSwap:"]
                total_kb += rss + swap
                process_count += 1
                if sample is not None:
                    contributors.append({"pid": identity[0], "pgid": identity[1],
                                         "start_ticks": identity[2], "rss_bytes": rss * 1024,
                                         "swap_bytes": swap * 1024})
                    contributors.sort(key=lambda row: row["rss_bytes"] + row["swap_bytes"], reverse=True)
                    del contributors[MEMORY_DIAGNOSTIC_PROCESS_LIMIT:]
            measured_bytes = total_kb * 1024 if process_count else None
            if sample is not None:
                sample.update(sampler="linux-proc", pgid=group_id, memory_bytes=measured_bytes,
                              process_count=process_count, processes=contributors,
                              processes_omitted=max(0, process_count - len(contributors)))
            return measured_bytes

        measured = subprocess.run(
            ["ps", "-axo", "pgid=,rss="],
            capture_output=True,
            text=True,
            timeout=2,
            check=False,
        )
        if measured.returncode == 0:
            rss_kb = 0
            found = False
            for line in measured.stdout.splitlines():
                fields = line.split()
                if len(fields) == 2 and int(fields[0]) == group_id:
                    found = True
                    rss_kb += int(fields[1])
            measured_bytes = rss_kb * 1024 if found else None
            if sample is not None:
                sample.update(sampler="ps-rss", pgid=group_id, memory_bytes=measured_bytes,
                              processes=[])
            return measured_bytes
    except (OSError, ValueError, subprocess.SubprocessError):
        return None
    return None


def process_memory_diagnostics(sample: dict) -> str:
    """Enrich the retained peak sample before killing, with bounded, redacted data."""
    diagnostic = dict(sample)
    diagnostic["sample_scope"] = "retained peak process-group sample"
    rows = []
    for original in sample.get("processes", [])[:MEMORY_DIAGNOSTIC_PROCESS_LIMIT]:
        row = dict(original)
        entry = POSIX_PROC_ROOT / str(row["pid"])
        identity = (row["pid"], row["pgid"], row["start_ticks"])
        if linux_process_identity(entry) != identity:
            row["identity_status"] = "changed-or-gone"
            rows.append(row)
            continue
        details = {}
        try:
            details["exe"] = os.readlink(entry / "exe")[:160]
        except OSError:
            details["exe"] = "unavailable"
        try:
            with (entry / "cmdline").open("rb") as stream:
                command = stream.read(513)
            # Do not print user arguments or environment. Counts still identify
            # a wrapper or plugin launcher without disclosing its payload.
            details["cmdline"] = {"arguments": "redacted", "argc_sampled": command[:512].count(b"\0"),
                                  "truncated": len(command) > 512}
        except OSError:
            details["cmdline"] = "unavailable"
        try:
            with (entry / "maps").open("rb") as stream:
                mappings = stream.read(16385)
            names = set()
            for line in mappings[:16384].decode("utf-8", errors="replace").splitlines():
                fields = line.split(None, 5)
                if len(fields) == 6 and ".so" in fields[5]:
                    names.add(Path(fields[5]).name[:80])
            # Keep LLVM/LTO plugin identities visible when many libraries load.
            libraries = sorted(names, key=lambda name: (not any(part in name.lower() for part in ("llvm", "lto", "gold")), name))
            details["libraries"] = libraries[:8]
            details["libraries_truncated"] = len(mappings) > 16384 or len(libraries) > 8
        except OSError:
            details["libraries"] = "unavailable"
        if linux_process_identity(entry) == identity:
            row.update(details, identity_status="matched")
        else:
            row["identity_status"] = "changed-during-diagnostics"
        rows.append(row)
    diagnostic["processes"] = rows
    return json.dumps(diagnostic, ensure_ascii=True, separators=(",", ":"))


class ProcessTree:
    def __init__(
        self,
        process: subprocess.Popen[bytes],
        windows_job: WindowsJob | None,
    ) -> None:
        self.process = process
        self.windows_job = windows_job
        self.peak_memory_sample: dict = {}

    @staticmethod
    def _rollback_spawn(process: subprocess.Popen[bytes] | None, windows_job: WindowsJob | None) -> None:
        if windows_job is None:
            return

        def retry_cleanup(action) -> Exception | None:
            for attempt in range(2):
                try:
                    action()
                    return None
                except Exception as error:
                    if attempt == 1:
                        return error
            return None

        wait_error = None
        close_error = None
        try:
            if process is not None:
                try:
                    retry_cleanup(windows_job.terminate)
                finally:
                    try:
                        def kill_launcher() -> None:
                            if process.poll() is None:
                                process.kill()

                        retry_cleanup(kill_launcher)
                    finally:
                        wait_error = retry_cleanup(lambda: process.wait(timeout=5))
        finally:
            close_error = retry_cleanup(windows_job.close)
        if wait_error is not None and close_error is None:
            # Closing a KILL_ON_JOB_CLOSE handle is also a termination path.
            # Reap again after that fallback when direct termination failed.
            wait_error = retry_cleanup(lambda: process.wait(timeout=5))
        failure = close_error if close_error is not None else wait_error
        if failure is not None:
            failed_steps = []
            if wait_error is not None:
                failed_steps.append("launcher reaping")
            if close_error is not None:
                failed_steps.append("Job handle close")
            raise RuntimeError(
                "Windows process startup rollback failed after bounded retries: " + ", ".join(failed_steps)
            ) from failure

    @classmethod
    def spawn(
        cls,
        command: list[str],
        memory_limit_bytes: int | None,
        *,
        executable: str | None = None,
        pass_fds: tuple[int, ...] = (),
    ) -> ProcessTree:
        if pass_fds and sys.platform.startswith("win"):
            raise RuntimeError("inherited file descriptors require a POSIX process")
        windows_job = WindowsJob(memory_limit_bytes) if sys.platform.startswith("win") else None
        popen_kwargs: dict[str, object] = {}
        if windows_job is not None:
            popen_kwargs["creationflags"] = 0x00000004  # CREATE_SUSPENDED
        else:
            popen_kwargs["start_new_session"] = True
        if executable is not None:
            popen_kwargs["executable"] = executable
        if pass_fds:
            popen_kwargs["pass_fds"] = pass_fds
        try:
            process = subprocess.Popen(
                command,
                cwd=ROOT,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                **popen_kwargs,
            )
        except BaseException:
            cls._rollback_spawn(None, windows_job)
            raise
        if windows_job is not None:
            try:
                windows_job.assign(process)
                windows_job.resume(process)
            except BaseException:
                cls._rollback_spawn(process, windows_job)
                raise
        return cls(process, windows_job)

    def memory_bytes(self) -> int | None:
        sample: dict = {}
        if self.windows_job is not None:
            measured = self.windows_job.memory_bytes()
            sample.update(sampler="windows-job", pid=self.process.pid, memory_bytes=measured)
        else:
            measured = posix_process_group_memory_bytes(self.process.pid, sample=sample)
        if measured is not None and measured >= self.peak_memory_sample.get("memory_bytes", 0):
            self.peak_memory_sample = sample
        return measured

    def memory_diagnostics(self) -> str:
        return process_memory_diagnostics(self.peak_memory_sample)

    def terminate(self) -> None:
        group_error = None
        try:
            if self.windows_job is not None:
                self.windows_job.terminate()
            else:
                try:
                    os.killpg(self.process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    # The group is already gone; launcher cleanup still runs below.
                    pass
        except Exception as error:
            group_error = error
            # A retired Windows Job re-raises its cached OS error. A launcher
            # failure belongs only to this attempt, not an earlier retry.
            group_error.launcher_cleanup_error = None
            raise
        finally:
            # A failed group/Job operation must not bypass launcher cleanup.
            try:
                if self.process.poll() is None:
                    self.process.kill()
            except Exception as error:
                if group_error is None:
                    raise
                # Preserve the first group failure and retain the independent
                # launcher error without replacing it or formatting payloads.
                group_error.launcher_cleanup_error = error

    def _final_cleanup(self) -> tuple[bool, bool, tuple[tuple[str, Exception], ...]]:
        errors: list[tuple[str, Exception]] = []

        def retry_cleanup(stage, action) -> bool:
            for _ in range(2):
                try:
                    action()
                    return True
                except Exception as error:
                    errors.append((stage, error))
            return False

        closed = False
        reaped = False
        try:
            def kill_launcher() -> None:
                if self.process.poll() is None:
                    self.process.kill()

            retry_cleanup("launcher kill", kill_launcher)
        finally:
            try:
                # KILL_ON_JOB_CLOSE is independent of TerminateJobObject.
                closed = retry_cleanup("resource close", self.close)
            finally:
                reaped = retry_cleanup("launcher reap", lambda: self.process.wait(timeout=5))
        return closed, reaped, tuple(errors)

    def close(self) -> None:
        if self.windows_job is not None:
            self.windows_job.close()


def run_with_heartbeat(
    command: list[str],
    *,
    label: str,
    timeout_seconds: int | None = None,
    memory_limit_mb: int | None = None,
    output_limit_mb: int = 8,
    executable: str | None = None,
    pass_fds: tuple[int, ...] = (),
) -> subprocess.CompletedProcess[str]:
    memory_limit_bytes = None
    if memory_limit_mb is not None:
        memory_limit_bytes = memory_limit_mb * 1024 * 1024
    spawn_kwargs: dict[str, object] = {}
    if executable is not None:
        spawn_kwargs["executable"] = executable
    if pass_fds:
        spawn_kwargs["pass_fds"] = pass_fds
    process_tree = ProcessTree.spawn(command, memory_limit_bytes, **spawn_kwargs)
    process = process_tree.process
    assert process.stdout is not None
    assert process.stderr is not None
    output_limit_bytes = output_limit_mb * 1024 * 1024
    stdout_capture = BoundedPipeCapture(output_limit_bytes)
    stderr_capture = BoundedPipeCapture(output_limit_bytes)
    stdout_thread = threading.Thread(
        target=stdout_capture.read_from,
        args=(process.stdout,),
        daemon=True,
    )
    stderr_thread = threading.Thread(
        target=stderr_capture.read_from,
        args=(process.stderr,),
        daemon=True,
    )
    stdout_thread.start()
    stderr_thread.start()
    started = time.monotonic()
    next_heartbeat = started + 30.0
    peak_memory_bytes = process_tree.memory_bytes() or 0
    process_tree_closed = False
    process_tree_cleanup_failure = None
    memory_diagnostic = ""
    guard_trigger = None
    guard_kind = None
    guard_error = None
    guard_observed_memory = None

    def refresh_guard_error() -> tuple[str, str, int, int]:
        nonlocal guard_error
        stdout_total, _, stdout_bytes = stdout_capture.snapshot()
        stderr_total, _, stderr_bytes = stderr_capture.snapshot()
        stdout = stdout_bytes.decode("utf-8", errors="replace")
        stderr = stderr_bytes.decode("utf-8", errors="replace")
        tails = f"stdout-tail={stdout[-2000:]}\nstderr-tail={stderr[-2000:]}"
        if guard_kind == "output":
            message = (
                f"{label} exceeded output limit: "
                f"stdout={stdout_total / (1024 * 1024):.1f}MB "
                f"stderr={stderr_total / (1024 * 1024):.1f}MB "
                f"limit={output_limit_mb}MB-per-stream\n{tails}"
            )
        elif guard_kind == "memory":
            metric = "observed" if guard_observed_memory is not None else "peak"
            amount = guard_observed_memory if guard_observed_memory is not None else peak_memory_bytes
            message = (
                f"{label} exceeded memory limit: {metric}={amount / (1024 * 1024):.1f}MB "
                f"limit={memory_limit_mb}MB\nmemory-sample={memory_diagnostic}\n{tails}"
            )
        else:
            message = None
        if message is not None:
            if guard_error is None:
                guard_error = RuntimeError(message)
            else:
                guard_error.args = (message,)
        elif guard_kind == "timeout" and guard_error is None:
            guard_error = subprocess.TimeoutExpired(command, timeout_seconds, output=stdout, stderr=stderr)
        if guard_error is not None:
            guard_error.output = stdout
            guard_error.stderr = stderr
            guard_error.stdout_total_bytes = stdout_total
            guard_error.stderr_total_bytes = stderr_total
            guard_error.guard_trigger = guard_trigger
            guard_error.guard_kind = guard_kind
        return stdout, stderr, stdout_total, stderr_total

    def record_guard(kind: str, observed_memory: int | None = None) -> RuntimeError | subprocess.TimeoutExpired:
        nonlocal guard_trigger, guard_kind, guard_observed_memory
        if guard_trigger is None:
            guard_trigger = kind
        guard_kind = kind
        guard_observed_memory = observed_memory
        # Snapshot without joining reader threads: preserve the original trigger
        # before termination, without delaying enforcement on a live process.
        refresh_guard_error()
        # Callers select a concrete guard kind; retain the same timeout object.
        assert guard_error is not None
        return guard_error

    def retain_completed_guard() -> None:
        if guard_trigger == "completed" and guard_error is None:
            if stdout_capture.snapshot()[1] or stderr_capture.snapshot()[1]:
                record_guard("output")
            elif memory_limit_bytes is not None and peak_memory_bytes > memory_limit_bytes:
                record_guard("memory")


    def stop_process_tree() -> None:
        nonlocal peak_memory_bytes, process_tree_closed, process_tree_cleanup_failure, memory_diagnostic
        if process_tree_closed:
            return
        if process_tree_cleanup_failure is not None:
            raise process_tree_cleanup_failure

        def capture_memory() -> None:
            nonlocal peak_memory_bytes, memory_diagnostic
            try:
                measured = process_tree.memory_bytes()
                if measured is not None:
                    peak_memory_bytes = max(peak_memory_bytes, measured)
                if memory_limit_bytes is not None and peak_memory_bytes > memory_limit_bytes and not memory_diagnostic:
                    # Capture before termination removes contributor identity.
                    memory_diagnostic = process_tree.memory_diagnostics()
            except Exception:
                # Optional evidence must neither prevent cleanup nor replace a
                # resource-limit failure. Do not format potentially sensitive
                # exception payloads or invoke the failed serializer again.
                if not memory_diagnostic:
                    memory_diagnostic = '{"diagnostic_error":"capture unavailable"}'

        try:
            capture_memory()
        finally:
            # Retry a transient OS failure before propagating the original
            # guard failure. Keep the Job handle and the cleanup state usable
            # until termination, reaping, and resource release have succeeded.
            errors: list[tuple[str, Exception]] = []
            group_terminated = False
            for attempt in range(2):
                stage = "group termination"
                try:
                    process_tree.terminate()
                    group_terminated = True
                    stage = "launcher reap"
                    if process.poll() is None:
                        process.wait(timeout=5)
                    try:
                        capture_memory()
                    finally:
                        stage = "resource close"
                        process_tree.close()
                        process_tree_closed = True
                    break
                except Exception as error:
                    errors.append((stage, error))
                    launcher_error = getattr(error, "launcher_cleanup_error", None)
                    if launcher_error is not None:
                        errors.append(("launcher kill", launcher_error))
            else:
                try:
                    capture_memory()
                finally:
                    closed, reaped, fallback_errors = process_tree._final_cleanup()
                errors.extend(fallback_errors)
                process_tree_closed = closed and reaped and (
                    group_terminated or process_tree.windows_job is not None
                )
                # Cleanup has already attempted termination and final reaping.
                # Let deferred readers retain their last bounded pipe bytes
                # before freezing the original guard and failure evidence.
                captured_text()
                retain_completed_guard()
                stdout, stderr, stdout_total, stderr_total = refresh_guard_error()
                guard_context = f"; guard-origin={guard_trigger}"
                if guard_kind == "timeout":
                    guard_context += (
                        f"; exceeded timeout: limit={timeout_seconds}s\n"
                        f"stdout-tail={stdout[-2000:]}\nstderr-tail={stderr[-2000:]}"
                    )
                elif guard_kind is not None:
                    guard_context += "; " + str(guard_error)
                if (
                    memory_limit_bytes is not None
                    and peak_memory_bytes > memory_limit_bytes
                    and (guard_kind != "memory" or guard_observed_memory is not None)
                ):
                    # Keep a measured cleanup peak alongside the original trigger.
                    # A completed memory guard already includes this same peak.
                    guard_context += (
                        f"; exceeded memory limit: peak={peak_memory_bytes / (1024 * 1024):.1f}MB "
                        f"limit={memory_limit_mb}MB\nmemory-sample={memory_diagnostic}"
                    )
                summary = ", ".join(
                    f"{step}:{type(error).__name__}:errno={getattr(error, 'errno', None)}"
                    f":winerror={getattr(error, 'winerror', None)}"
                    for step, error in errors
                )
                process_tree_cleanup_failure = RuntimeError(
                    f"{label} process-tree cleanup failed after 2 attempts; "
                    f"final fallback resource-closed={closed} launcher-reaped={reaped} "
                    f"tree-closed={process_tree_closed}; "
                    f"failures={summary}{guard_context}"
                )
                process_tree_cleanup_failure.cleanup_errors = tuple(errors)
                process_tree_cleanup_failure.guard_error = guard_error
                process_tree_cleanup_failure.guard_trigger = guard_trigger
                process_tree_cleanup_failure.output = stdout
                process_tree_cleanup_failure.stderr = stderr
                process_tree_cleanup_failure.stdout_total_bytes = stdout_total
                process_tree_cleanup_failure.stderr_total_bytes = stderr_total
                raise process_tree_cleanup_failure from errors[0][1]

    def captured_text() -> tuple[str, str]:
        stdout_thread.join(timeout=5)
        stderr_thread.join(timeout=5)
        stdout_bytes = stdout_capture.snapshot()[2]
        stderr_bytes = stderr_capture.snapshot()[2]
        return (
            stdout_bytes.decode("utf-8", errors="replace"),
            stderr_bytes.decode("utf-8", errors="replace"),
        )

    try:
        while True:
            stdout_total, stdout_exceeded, _ = stdout_capture.snapshot()
            stderr_total, stderr_exceeded, _ = stderr_capture.snapshot()
            if stdout_exceeded or stderr_exceeded:
                trigger_error = record_guard("output")
                stop_process_tree()
                captured_text()
                refresh_guard_error()
                raise trigger_error

            measured_memory = process_tree.memory_bytes()
            if measured_memory is not None:
                peak_memory_bytes = max(peak_memory_bytes, measured_memory)
                if memory_limit_bytes is not None and measured_memory > memory_limit_bytes:
                    trigger_error = record_guard("memory", measured_memory)
                    stop_process_tree()
                    captured_text()
                    refresh_guard_error()
                    raise trigger_error

            wait_seconds = 0.25
            if timeout_seconds is not None:
                elapsed = time.monotonic() - started
                remaining = timeout_seconds - elapsed
                if remaining <= 0:
                    trigger_error = record_guard("timeout")
                    stop_process_tree()
                    captured_text()
                    refresh_guard_error()
                    raise trigger_error
                wait_seconds = min(wait_seconds, remaining)

            try:
                process.wait(timeout=wait_seconds)
                guard_trigger = "completed"
                stop_process_tree()
                stdout, stderr = captured_text()
                retain_completed_guard()
                if guard_error is not None:
                    refresh_guard_error()
                    raise guard_error
                elapsed_seconds = time.monotonic() - started
                print(
                    f"{label} complete elapsed={elapsed_seconds:.1f}s "
                    f"peak-memory={peak_memory_bytes / (1024 * 1024):.1f}MB",
                    flush=True,
                )
                return subprocess.CompletedProcess(
                    command,
                    process.returncode,
                    stdout,
                    stderr,
                )
            except subprocess.TimeoutExpired:
                now = time.monotonic()
                if now >= next_heartbeat:
                    elapsed_seconds = int(now - started)
                    print(
                        f"{label} pending elapsed={elapsed_seconds}s "
                        f"peak-memory={peak_memory_bytes / (1024 * 1024):.1f}MB",
                        flush=True,
                    )
                    next_heartbeat = now + 30.0
    except BaseException:
        if process_tree_cleanup_failure is None:
            stop_process_tree()
        raise


def process_is_running(process_id: int) -> bool:
    if sys.platform.startswith("win"):
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
        kernel32.OpenProcess.restype = wintypes.HANDLE
        kernel32.GetExitCodeProcess.argtypes = [wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD)]
        kernel32.GetExitCodeProcess.restype = wintypes.BOOL
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
        kernel32.CloseHandle.restype = wintypes.BOOL
        handle = kernel32.OpenProcess(0x1000, False, process_id)
        if not handle:
            return False
        try:
            exit_code = wintypes.DWORD()
            return bool(kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code))) and exit_code.value == 259
        finally:
            kernel32.CloseHandle(handle)

    status_path = Path(f"/proc/{process_id}/status")
    if status_path.exists():
        try:
            for line in status_path.read_text(encoding="ascii", errors="replace").splitlines():
                if line.startswith("State:"):
                    return "Z" not in line.split()[1]
        except OSError:
            return False
    try:
        measured = subprocess.run(
            ["ps", "-o", "stat=", "-p", str(process_id)],
            capture_output=True,
            text=True,
            timeout=2,
            check=False,
        )
        state = measured.stdout.strip()
        if measured.returncode != 0 or not state:
            return False
        return not state.startswith("Z")
    except (OSError, subprocess.SubprocessError):
        pass
    try:
        os.kill(process_id, 0)
        return True
    except (ProcessLookupError, PermissionError):
        return False


def check_process_tree_guard() -> None:
    child_code = "import time; time.sleep(30)"
    parent_code = (
        "import subprocess,sys; "
        f"child=subprocess.Popen([sys.executable,'-c',{child_code!r}]); "
        "print(f'guard-child={child.pid}', file=sys.stderr, flush=True)"
    )
    executed = run_with_heartbeat(
        [sys.executable, "-c", parent_code],
        label="process-tree guard self-test",
        timeout_seconds=10,
        memory_limit_mb=64,
    )
    match = re.search(r"guard-child=(\d+)", executed.stderr)
    if executed.returncode != 0 or match is None:
        raise RuntimeError("process-tree guard self-test did not report its descendant")
    child_id = int(match.group(1))
    deadline = time.monotonic() + 2.0
    while process_is_running(child_id) and time.monotonic() < deadline:
        time.sleep(0.05)
    if process_is_running(child_id):
        raise RuntimeError(f"process-tree guard left descendant {child_id} running")
    print("process-tree guard: descendant terminated")


def compile_runtime_smoke(
    clang: str,
    include_arg: str,
    runtime_smoke_c: Path,
    runtime_source: str,
    fixture: Path,
    c_source: str,
    extra_cflags: tuple[str, ...] = (),
) -> tuple[Path, bool]:
    suffix = ".exe" if sys.platform.startswith("win") else ""
    c_path = RUNTIME_BUILD_ROOT / f"{fixture.stem}.fk.c"
    exe_path = RUNTIME_BUILD_ROOT / f"{fixture.stem}{suffix}"
    stamp_path = RUNTIME_BUILD_ROOT / f"{fixture.stem}.compile.sha256"
    platform_link_args = runtime_platform_link_args()
    compile_key = hash_text(
        "v4-runtime-smoke-v2",
        clang,
        runtime_source,
        c_source,
        *extra_cflags,
        *runtime_platform_cache_parts(include_arg),
    )

    write_text_if_changed(c_path, c_source)
    if exe_path.exists() and stamp_path.exists() and read_text(stamp_path).strip() == compile_key:
        return exe_path, False

    compile_cmd = [
        clang,
        "-o",
        str(exe_path),
        str(c_path),
        str(runtime_smoke_c),
        include_arg,
        "-w",
        "-O0",
        *extra_cflags,
        *platform_link_args,
    ]
    compiled = run_with_heartbeat(
        compile_cmd,
        label=f"runtime compile: {rel(fixture)}",
        memory_limit_mb=1024,
    )
    if compiled.returncode != 0:
        print(f"runtime compile failed: {rel(fixture)}")
        print(compiled.stdout)
        print(compiled.stderr)
        raise SystemExit(1)

    stamp_path.write_text(compile_key, encoding="utf-8")
    return exe_path, True


def parse_smoke_shard(spec: str) -> tuple[int, int] | None:
    if not spec:
        return None

    parts = spec.split("/", 1)
    if len(parts) != 2:
        print(f"runtime smoke failed: invalid shard spec {spec!r}; use INDEX/TOTAL")
        raise SystemExit(1)

    try:
        index = int(parts[0])
        total = int(parts[1])
    except ValueError:
        print(f"runtime smoke failed: invalid shard spec {spec!r}; INDEX and TOTAL must be integers")
        raise SystemExit(1)

    if total <= 0 or index <= 0 or index > total:
        print(f"runtime smoke failed: invalid shard spec {spec!r}; need 1 <= INDEX <= TOTAL")
        raise SystemExit(1)

    return index - 1, total


def apply_smoke_shard(smokes: list[dict[str, object]], shard_spec: str) -> list[dict[str, object]]:
    shard = parse_smoke_shard(shard_spec)
    if shard is None:
        return smokes

    shard_index, shard_total = shard
    selected = [smoke for idx, smoke in enumerate(smokes) if idx % shard_total == shard_index]
    if selected:
        return selected

    print(f"runtime smoke failed: shard {shard_spec!r} matched no executable smokes")
    raise SystemExit(1)


def filter_smokes(filters: list[str]) -> list[dict[str, object]]:
    if not filters:
        return list(EXECUTABLE_SMOKES)

    lowered = [item.lower() for item in filters]
    selected: list[dict[str, object]] = []
    for smoke in EXECUTABLE_SMOKES:
        haystacks = [
            smoke["name"],
            smoke["fixture"],
            Path(smoke["fixture"]).stem,
        ]
        if any(needle in haystack.lower() for needle in lowered for haystack in haystacks):
            selected.append(smoke)

    if selected:
        return selected

    print("runtime smoke failed: no smoke matched filters")
    for needle in filters:
        print(f"filter: {needle}")
    for smoke in EXECUTABLE_SMOKES:
        print(f"available smoke: {smoke['name']} fixture={smoke['fixture']}")
    raise SystemExit(1)


def exclude_smokes(smokes: list[dict[str, object]], excludes: list[str]) -> list[dict[str, object]]:
    if not excludes:
        return smokes

    lowered = [item.lower() for item in excludes]
    kept: list[dict[str, object]] = []
    removed = 0
    for smoke in smokes:
        haystacks = [
            smoke["name"],
            smoke["fixture"],
            Path(smoke["fixture"]).stem,
        ]
        if any(needle in haystack.lower() for needle in lowered for haystack in haystacks):
            removed += 1
            continue
        kept.append(smoke)

    if kept:
        return kept

    print("runtime smoke failed: exclusions removed every selected smoke")
    print(f"selected={len(smokes)} excluded={removed}")
    for needle in excludes:
        print(f"exclude: {needle}")
    raise SystemExit(1)


def select_smokes(filters: list[str], excludes: list[str], shard_spec: str) -> list[dict[str, object]]:
    selected = filter_smokes(filters)
    selected = exclude_smokes(selected, excludes)
    return apply_smoke_shard(selected, shard_spec)


def keyed_output_prefix(line: str) -> str | None:
    """Return the stable key prefix for a key=value output record."""
    for marker in ("|ok=", "|pass=", "|status="):
        prefix, separator, _ = line.partition(marker)
        if separator and prefix:
            return prefix + separator

    key, separator, _ = line.partition("=")
    if not separator or not key or "|" in key:
        return None
    return key + separator


def unique_output_failures(
    registered_lines: list[str], output_line_counts: Counter[str]
) -> list[tuple[str, int, int, int | None]]:
    failures: list[tuple[str, int, int, int | None]] = []
    registered_counts = Counter(registered_lines)
    for line, registered_count in registered_counts.items():
        output_count = output_line_counts[line]
        key_prefix = keyed_output_prefix(line)
        keyed_output_count = None
        if key_prefix is not None:
            keyed_output_count = sum(
                count
                for output_line, count in output_line_counts.items()
                if output_line.startswith(key_prefix)
            )
        if (
            registered_count != 1
            or output_count != 1
            or (keyed_output_count is not None and keyed_output_count != 1)
        ):
            failures.append(
                (line, registered_count, output_count, keyed_output_count)
            )
    return failures


def check_llvm_runtime_primitives(clang: str, include_arg: str) -> None:
    source_path = RUNTIME_BUILD_ROOT / "llvm_runtime_primitives_smoke.c"
    exe_suffix = ".exe" if sys.platform.startswith("win") else ""
    exe_path = RUNTIME_BUILD_ROOT / f"llvm_runtime_primitives_smoke{exe_suffix}"
    stamp_path = RUNTIME_BUILD_ROOT / "llvm_runtime_primitives_smoke.compile.sha256"
    runtime_c = RUNTIME_ROOT / "freak_runtime.c"
    llvm_runtime_c = RUNTIME_ROOT / "freak_llvm_runtime.c"
    source = r'''#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int64_t freak_llvm_array_new(void);
void freak_llvm_array_push(int64_t handle, int64_t item);
int64_t freak_llvm_array_get(int64_t handle, int64_t index);
int64_t freak_llvm_array_len(int64_t handle);
void freak_llvm_array_release(int64_t handle);
int64_t freak_llvm_word_join(int64_t handle);
int64_t freak_llvm_word_substring(int64_t value, int64_t start, int64_t length);
void freak_llvm_word_release_replaced(int64_t previous, int64_t replacement);

int main(void) {
    for (int64_t index = 0; index < 1100; index++) {
        int64_t handle = freak_llvm_array_new();
        freak_llvm_array_push(handle, (int64_t)(intptr_t)"reused");
        int64_t joined = freak_llvm_word_join(handle);
        if (strcmp((const char*)(intptr_t)joined, "reused") != 0) return 10;
        freak_llvm_word_release_replaced(joined, 0);
    }

    int64_t released = freak_llvm_array_new();
    freak_llvm_array_release(released);
    int64_t reused = freak_llvm_array_new();
    if (reused == released) return 11;
    freak_llvm_array_push(released, (int64_t)(intptr_t)"stale");
    if (freak_llvm_array_len(released) != 0) return 12;
    if (freak_llvm_array_len(reused) != 0) return 13;
    freak_llvm_array_push(reused, (int64_t)(intptr_t)"fresh");
    if (freak_llvm_array_len(reused) != 1) return 14;
    if (strcmp((const char*)(intptr_t)freak_llvm_array_get(reused, 0), "fresh") != 0) return 15;
    freak_llvm_array_release(reused);

    int64_t sliced = freak_llvm_word_substring(
        (int64_t)(intptr_t)"Alternative", 3, 5
    );
    if (strcmp((const char*)(intptr_t)sliced, "ernat") != 0) return 16;
    freak_llvm_word_release_replaced(sliced, 0);
    puts("llvm-runtime-primitives=ok");
    return 0;
}
'''
    runtime_source = read_text(runtime_c)
    llvm_runtime_source = read_text(llvm_runtime_c)
    platform_link_args = runtime_platform_link_args()
    compile_key = hash_text(
        "v4-llvm-runtime-primitives-v2",
        clang,
        source,
        runtime_source,
        llvm_runtime_source,
        *runtime_platform_cache_parts(include_arg),
    )
    write_text_if_changed(source_path, source)

    compiled_now = not (
        exe_path.exists()
        and stamp_path.exists()
        and read_text(stamp_path).strip() == compile_key
    )
    if compiled_now:
        compile_cmd = [
            clang,
            "-o",
            str(exe_path),
            str(source_path),
            str(runtime_c),
            str(llvm_runtime_c),
            include_arg,
            "-w",
            "-O0",
            *platform_link_args,
        ]
        compiled = run_with_heartbeat(
            compile_cmd,
            label="LLVM runtime primitive compile",
            memory_limit_mb=512,
        )
        if compiled.returncode != 0:
            print("LLVM runtime primitive compile failed")
            print((compiled.stdout + compiled.stderr)[:4000])
            raise SystemExit(1)
        stamp_path.write_text(compile_key, encoding="utf-8")

    executed = run_with_heartbeat(
        [str(exe_path)],
        label="LLVM runtime primitive execute",
        timeout_seconds=30,
        memory_limit_mb=64,
    )
    output = executed.stdout + executed.stderr
    if executed.returncode != 0 or output.splitlines() != ["llvm-runtime-primitives=ok"]:
        print(f"LLVM runtime primitive smoke failed: exit={executed.returncode}")
        print(output[:4000])
        raise SystemExit(1)
    compile_mode = "clang" if compiled_now else "cache"
    print(f"LLVM runtime primitives: compile={compile_mode} output_bytes={len(output)}")


def check_native_snapshot_lines(clang: str) -> None:
    """Fault-inject and measure both production snapshot splitter backends."""
    source_path = ROOT / "tests" / "native_snapshot_lines.c"
    suffix = ".exe" if sys.platform.startswith("win") else ""
    exe_path = RUNTIME_BUILD_ROOT / f"native_snapshot_lines{suffix}"
    stamp_path = RUNTIME_BUILD_ROOT / "native_snapshot_lines.sha256"
    include_arg = f"-I{RUNTIME_ROOT}"
    build_key = hash_text(
        "v4-native-snapshot-lines-v2", clang, read_text(source_path),
        *runtime_platform_cache_parts(include_arg),
        *(read_text(RUNTIME_ROOT / name) for name in (
            "freak_runtime.c", "freak_runtime.h", "freak_llvm_runtime.c",
        )),
    )
    compiled_now = not (
        exe_path.exists() and stamp_path.exists()
        and read_text(stamp_path).strip() == build_key
    )
    if compiled_now:
        linked = run_with_heartbeat(
            [clang, "-O1", str(source_path), include_arg, "-o", str(exe_path),
             *runtime_platform_link_args()],
            label="native snapshot lines compile", memory_limit_mb=1024,
        )
        if linked.returncode != 0:
            raise RuntimeError("Native snapshot line test compile failed\n" +
                               (linked.stdout + linked.stderr)[-4000:])
    executed = run_with_heartbeat(
        [str(exe_path)], label="native snapshot lines execute",
        timeout_seconds=30, memory_limit_mb=64,
    )
    if executed.returncode != 0 or "native_snapshot_lines PASS" not in executed.stdout.splitlines():
        raise RuntimeError("Native snapshot line test failed\n" +
                           (executed.stdout + executed.stderr)[-4000:])
    if compiled_now:
        stamp_path.write_text(build_key, encoding="utf-8")
    print(executed.stdout.strip())


def check_v3_llvm_substring_pipeline(clang: str, include_arg: str) -> None:
    suffix = ".exe" if sys.platform.startswith("win") else ""
    compiler_source_path = RUNTIME_BUILD_ROOT / "v3_llvm_substring_compiler.fk"
    compiler_c_path = Path(str(compiler_source_path) + ".c")
    stage0_path = RUNTIME_BUILD_ROOT / f"v3_llvm_substring_stage0{suffix}"
    stage2_path = RUNTIME_BUILD_ROOT / f"v3_llvm_substring_stage2{suffix}"
    fixture_path = RUNTIME_BUILD_ROOT / "v3_llvm_substring.fk"
    llvm_path = Path(str(fixture_path) + ".ll")
    exe_path = RUNTIME_BUILD_ROOT / f"v3_llvm_substring{suffix}"
    stamp_path = RUNTIME_BUILD_ROOT / "v3_llvm_substring_pipeline.sha256"
    bootstrap_c_path = ROOT / "build" / "freakc_v3.fk.c"
    runtime_c = RUNTIME_ROOT / "freak_runtime.c"
    llvm_runtime_c = RUNTIME_ROOT / "freak_llvm_runtime.c"
    v3_sources = [
        ROOT / "src" / "compiler" / "v3" / name
        for name in (
            "globals.fk",
            "helpers.fk",
            "lexer.fk",
            "parser.fk",
            "checker.fk",
            "emit_c.fk",
            "emit_llvm.fk",
            "main.fk",
        )
    ]
    compiler_source = "\n".join(read_text(path) for path in v3_sources)
    index_body = freak_task_body(
        read_text(crate_path("freak_hir")), "v4_hir_snapshot_index_lines"
    )
    if index_body is None:
        raise RuntimeError("V3 LLVM line-index regression cannot extract the HIR helper")
    fixture_source = (
        "task v4_hir_snapshot_index_lines(payload: word) -> int {\n"
        + index_body
        + "\n}\n"
        + r'''
task main() {
say "Alternative".substring(3, 5)
pilot empty_lines = v4_hir_snapshot_index_lines("")
pilot empty_ok = empty_lines >= 0 and array_len(empty_lines) == 0
array_release(empty_lines)
pilot lines = v4_hir_snapshot_index_lines("\nA\r\n\n")
pilot first: word = array_get(lines, 0)
pilot middle: word = array_get(lines, 1)
pilot blank: word = array_get(lines, 2)
pilot trailing: word = array_get(lines, 3)
pilot small_ok = lines >= 0 and array_len(lines) == 4 and first == "" and middle == "A\r" and blank == "" and trailing == ""
array_release(lines)
pilot parts = array_new()
pilot row: word = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789----"
pilot i = 0
repeat until i >= 8192 {
    array_push(parts, row)
    array_push(parts, "\n")
    i += 1
}
pilot payload: word = word_join(parts)
pilot large = v4_hir_snapshot_index_lines(payload)
pilot large_first: word = array_get(large, 0)
pilot large_last: word = array_get(large, 8191)
pilot large_trailing: word = array_get(large, 8192)
pilot large_ok = large >= 0 and array_len(large) == 8193 and large_first == row and large_last == row and large_trailing == ""
array_release(large)
if empty_ok and small_ok and large_ok {
    say "llvm-hir-line-index=ok"
} else {
    say "llvm-hir-line-index=failed"
}
}
'''
    )
    bootstrap_c = read_text(bootstrap_c_path)
    runtime_source = read_text(runtime_c)
    llvm_runtime_source = read_text(llvm_runtime_c)
    platform_link_args = runtime_platform_link_args()
    final_link_args = runtime_platform_final_link_args()
    pipeline_key = hash_text(
        "v4-v3-llvm-substring-pipeline-v2",
        clang,
        bootstrap_c,
        compiler_source,
        fixture_source,
        runtime_source,
        llvm_runtime_source,
        *runtime_platform_cache_parts(include_arg, final_link=True),
    )
    write_text_if_changed(compiler_source_path, compiler_source)
    write_text_if_changed(fixture_path, fixture_source)

    compiled_now = not (
        exe_path.exists()
        and stamp_path.exists()
        and read_text(stamp_path).strip() == pipeline_key
    )
    if compiled_now:
        stage0 = run_with_heartbeat(
            [
                clang,
                "-o",
                str(stage0_path),
                str(bootstrap_c_path),
                str(runtime_c),
                include_arg,
                "-w",
                "-O0",
                *platform_link_args,
            ],
            label="V3 LLVM substring stage0 compile",
            memory_limit_mb=1024,
        )
        if stage0.returncode != 0:
            raise RuntimeError(
                "V3 LLVM substring stage0 compile failed\n"
                + (stage0.stdout + stage0.stderr)[-4000:]
            )

        transpiled = run_with_heartbeat(
            [str(stage0_path), str(compiler_source_path), "--c"],
            label="V3 LLVM substring current compiler transpile",
            timeout_seconds=300,
            memory_limit_mb=512,
        )
        if transpiled.returncode != 0 or not compiler_c_path.exists():
            raise RuntimeError(
                "V3 LLVM substring current compiler transpile failed\n"
                + (transpiled.stdout + transpiled.stderr)[-4000:]
            )

        stage2 = run_with_heartbeat(
            [
                clang,
                "-o",
                str(stage2_path),
                str(compiler_c_path),
                str(runtime_c),
                include_arg,
                "-w",
                "-O0",
                *platform_link_args,
            ],
            label="V3 LLVM substring current compiler link",
            memory_limit_mb=1024,
        )
        if stage2.returncode != 0:
            raise RuntimeError(
                "V3 LLVM substring current compiler link failed\n"
                + (stage2.stdout + stage2.stderr)[-4000:]
            )

        emitted = run_with_heartbeat(
            [str(stage2_path), str(fixture_path), "--llvm", "--opt=0"],
            label="V3 LLVM substring emit",
            timeout_seconds=120,
            memory_limit_mb=512,
        )
        if emitted.returncode != 0 or not llvm_path.exists():
            raise RuntimeError(
                "V3 LLVM substring emit failed\n"
                + (emitted.stdout + emitted.stderr)[-4000:]
            )
        llvm_source = read_text(llvm_path)
        if "@freak_llvm_word_substring" not in llvm_source:
            raise RuntimeError("V3 LLVM substring emit omitted the runtime call")

        link_command = [
            clang,
            "-o",
            str(exe_path),
            str(llvm_path),
            str(llvm_runtime_c),
            str(runtime_c),
            include_arg,
            "-w",
            "-O0",
            *final_link_args,
        ]
        linked = run_with_heartbeat(
            link_command,
            label="V3 LLVM substring native link",
            memory_limit_mb=1024,
        )
        if linked.returncode != 0:
            raise RuntimeError(
                "V3 LLVM substring native link failed\n"
                + (linked.stdout + linked.stderr)[-4000:]
            )

    executed = run_with_heartbeat(
        [str(exe_path)],
        label="V3 LLVM substring execute",
        timeout_seconds=30,
        memory_limit_mb=64,
    )
    if executed.returncode != 0 or executed.stdout.splitlines() != ["ernat", "llvm-hir-line-index=ok"]:
        raise RuntimeError(
            "V3 LLVM substring pipeline execution failed\n"
            + (executed.stdout + executed.stderr)[-4000:]
        )
    if compiled_now:
        stamp_path.write_text(pipeline_key, encoding="utf-8")
    compile_mode = "bootstrap" if compiled_now else "cache"
    print(f"V3 LLVM substring pipeline: compile={compile_mode}")


def checked_source_fixture_paths() -> list[str]:
    directory = RUNTIME_BUILD_ROOT / "h6_source_directory"
    directory.mkdir(parents=True, exist_ok=True)
    missing = directory / "missing.fk"
    if missing.exists():
        raise RuntimeError(f"checked source fixture requires an absent path: {missing}")
    return [
        str(TESTS_ROOT / "data" / "h6_io_empty_source.fk"),
        str(TESTS_ROOT / "data" / "h6_io_readable_source.fk"),
        str(missing),
        str(directory),
    ]


def expected_native_stdout(text: str) -> str:
    """Expected bytes decoded from a C text stream, including Windows LF writes."""
    return text.replace("\n", "\r\n") if sys.platform == "win32" else text


def llvm_text_floor_module():
    """llvm_text_floor, imported on first use so frozen-source loaders of
    this file need nothing beside it."""
    here = str(V4_ROOT)
    if here not in sys.path:
        sys.path.insert(0, here)
    import llvm_text_floor
    return llvm_text_floor


def check_llvm_text_floor() -> None:
    """B0: the text backend's LLVM floor and its guard reject what they must."""
    floor = llvm_text_floor_module()
    accepted = (
        'define ccc i64 @f(ptr noalias sret(%"freak.shape.V") align 8 %r) nounwind {\n'
        '  %a = getelementptr inbounds i8, ptr %r, i64 8\n  %b = mul i64 1, 2\n  ret i64 %b\n}\n'
        '@s = private constant [24 x i8] c"memory(none) i8* zext nneg"\n'
        '; trunc nuw i8* captures(none)\n'
    )
    rejected = {
        "%x = load i8*, ptr %p": "typed pointer",
        'declare void @f(%"freak.shape.A"*)': "typed pointer",
        "%c = call i64 (i64)* @g(i64 1)": "typed pointer",
        "define void @f() memory(none) {": "LLVM 16",
        "%a = zext nneg i32 %b to i64": "LLVM 18",
        "%a = or disjoint i64 %b, %c": "LLVM 18",
        "%a = trunc nuw i64 %b to i32": "LLVM 19",
        "%a = getelementptr inbounds nuw i8, ptr %p, i64 1": "LLVM 19",
        "declare void @f(ptr captures(none))": "LLVM 21",
        "%a = icmp samesign ult i64 %b, %c": "LLVM 20",
    }
    if floor.MIN_LLVM_MAJOR != 15 or floor.text_floor_problems(accepted):
        raise RuntimeError(f"LLVM text floor rejected valid text: {floor.text_floor_problems(accepted)}")
    for text, needle in rejected.items():
        problems = floor.text_floor_problems(text)
        if len(problems) != 1 or needle not in problems[0]:
            raise RuntimeError(f"LLVM text floor missed {text!r}: {problems}")
    versions = {
        "Ubuntu clang version 18.1.3 (1ubuntu1)": 18,
        "Apple clang version 15.0.0 (clang-1500.3.9.4)": 15,
        "clang version 14.0.6\nTarget: x86_64-pc-linux-gnu": 14,
        "gcc (GCC) 13.2.0": None,
    }
    for text, major in versions.items():
        if floor.clang_major(text) != major:
            raise RuntimeError(f"clang version parse failed: {text!r}")
    doctor = (ROOT / "src" / "cli" / "doctor.fk").read_text(encoding="utf-8")
    for constant in ("CLI_DOCTOR_MINIMUM_CLANG_MAJOR", "CLI_DOCTOR_MINIMUM_APPLE_CLANG_MAJOR"):
        if not re.search(rf"^pilot {constant}: int = {floor.MIN_LLVM_MAJOR}\r?$", doctor, re.MULTILINE):
            raise RuntimeError(f"freak doctor's {constant} disagrees with MIN_LLVM_MAJOR")
    print(f"LLVM text floor: min-major={floor.MIN_LLVM_MAJOR} rejected={len(rejected)}")


def extract_llvm_modules(output: str) -> list[str]:
    """Accept C text-stream framing while retaining each module's bytes."""
    return re.findall(r"^@@LLVM-MODULE-BEGIN\r?\n(.*?)\r?\n@@LLVM-MODULE-END\r?$",
                      output, re.DOTALL | re.MULTILINE)


def prepare_source_fifo(fifo: Path) -> None:
    """Reuse a real FIFO, replacing stale files without following symlinks."""
    try:
        mode = fifo.lstat().st_mode
    except FileNotFoundError:
        mode = None
    if mode is not None:
        if stat.S_ISFIFO(mode):
            return
        if stat.S_ISDIR(mode):
            fifo.rmdir()  # Only an empty generated directory may be replaced.
        else:
            fifo.unlink()
    os.mkfifo(fifo)


def check_checked_source_runtime(clang: str) -> None:
    fixture = TESTS_ROOT / "h6_source_read_checked_runtime.c"
    executable = RUNTIME_BUILD_ROOT / ("h6_source_read.exe" if sys.platform == "win32" else "h6_source_read")
    stamp = executable.with_suffix(".compile.sha256")
    key = hash_text(
        "checked-source-runtime-v1", clang, read_text(fixture),
        read_text(RUNTIME_ROOT / "freak_runtime.c"),
        read_text(RUNTIME_ROOT / "freak_runtime.h"),
        *runtime_platform_link_args(),
    )
    if not executable.exists() or not stamp.exists() or read_text(stamp).strip() != key:
        compiled = run_with_heartbeat(
            [clang, str(fixture), "-o", str(executable),
             f"-DFREAK_ARRAY_LIVE_LIMIT={C_ARRAY_HANDLE_RESOURCE_LIMIT}",
             *runtime_platform_link_args()],
            label="checked source runtime compile", timeout_seconds=60,
            memory_limit_mb=512,
        )
        if compiled.returncode != 0:
            raise RuntimeError(f"checked source runtime compile failed:\n{compiled.stdout}{compiled.stderr}")
        stamp.write_text(key + "\n", encoding="utf-8")
    paths = checked_source_fixture_paths()
    if hasattr(os, "mkfifo"):
        fifo = RUNTIME_BUILD_ROOT / "h6_source_fifo"
        prepare_source_fifo(fifo)
        paths.append(str(fifo))
    executed = run_with_heartbeat(
        [str(executable), *paths], label="checked source runtime execute",
        timeout_seconds=10, memory_limit_mb=64,
    )
    expected = "h6-runtime-source-read contents=true errors=true faults=true recovery=true\n"
    if executed.returncode != 0 or executed.stdout != expected_native_stdout(expected) or executed.stderr:
        raise RuntimeError(f"checked source runtime failed:\n{executed.stdout}{executed.stderr}")
    print(expected.strip())



