NATIVE_PATTERNS_ROUTES = "route Shape {\n    Dot { x: int, y: int }\n    Empty\n}\nroute Wrap {\n    One { inner: Shape }\n    Nothing\n}\n"


def check_v4_native_patterns() -> None:
    """Build and run the patterns program exactly; refuse what is still out of scope."""
    source = V4_ROOT / "examples" / "patterns_native.fk"
    executable = RUNTIME_BUILD_ROOT / ("tier3_native_patterns.exe" if sys.platform == "win32" else "tier3_native_patterns.native")
    executable.unlink(missing_ok=True)
    built = run_with_heartbeat(
        [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(executable)],
        label="V4 build command: native patterns", timeout_seconds=180, memory_limit_mb=512,
    )
    if built.returncode != 0 or not executable.exists():
        raise RuntimeError(f"V4 rejected the native patterns program:\n{built.stdout}{built.stderr}")
    ran = run_with_heartbeat([str(executable)], label="V4 native patterns execute", timeout_seconds=10, memory_limit_mb=128)
    if ran.returncode != NATIVE_PATTERNS_EXIT or ran.stdout.replace("\r\n", "\n") != NATIVE_PATTERNS_EXPECTED:
        raise RuntimeError(f"V4 native patterns printed the wrong output: exit={ran.returncode} stdout={ran.stdout!r}")
    # Every target gets a module the layout oracle accepts.
    probes = 0
    for triple in NATIVE_LAYOUT_TRIPLES:
        module_path = RUNTIME_BUILD_ROOT / f"tier3_native_patterns_{triple}.ll"
        module_path.unlink(missing_ok=True)
        emitted = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(module_path), "--emit-llvm", "--target", triple],
            label=f"V4 patterns module {triple}", timeout_seconds=180, memory_limit_mb=512,
        )
        if emitted.returncode != 0 or not module_path.exists():
            raise RuntimeError(f"V4 could not emit the patterns module for {triple}:\n{emitted.stdout}{emitted.stderr}")
        probes += check_native_layout_oracle(module_path.read_text(encoding="utf-8"), triple)
    routes = NATIVE_PATTERNS_ROUTES
    rejected_cases = (
        ("tier3_pattern_guard", "task f(n: int) -> int {\n    when n {\n        x if x > 3 -> give back 1\n        _ -> give back 0\n    }\n    give back 2\n}\n"
         "task main() -> int { give back f(5) }\n", "unsupported when arm pattern"),
        ("tier3_pattern_shape", "shape Point { x: int, y: int }\ntask f(p: Point) -> int {\n    when p {\n        Point { x, y } -> give back x + y\n    }\n    give back 0\n}\n"
         "task main() -> int { give back f(Point { x: 1, y: 2 }) }\n", "unsupported when arm pattern"),
        # A refutable nested pattern does not cover its outer case.
        ("tier3_pattern_nested_not_exhaustive", routes + "task f(w: Wrap) -> int {\n    when w {\n        Wrap::One { inner: Shape::Empty } -> give back 1\n"
         "        Wrap::Nothing -> give back 0\n    }\n    give back 2\n}\ntask main() -> int { give back f(Wrap::Nothing) }\n",
         "non-exhaustive route when|missing Wrap::One"),
        ("tier3_check_route_nested_not_exhaustive", routes + "task f(w: Wrap) -> int {\n    check route w {\n"
         "        One { inner: Shape::Dot { x, y } } -> give back x + y\n        Nothing -> give back 0\n    }\n    give back 2\n}\n"
         "task main() -> int { give back f(Wrap::Nothing) }\n", "non-exhaustive check route|missing Wrap::One"),
        ("tier3_pattern_covered_arm", routes + "task f(w: Wrap) -> int {\n    when w {\n        Wrap::One { inner } -> give back 1\n"
         "        Wrap::One { inner: Shape::Empty } -> give back 2\n        Wrap::Nothing -> give back 0\n    }\n    give back 2\n}\n"
         "task main() -> int { give back f(Wrap::Nothing) }\n", "unreachable when arm|Wrap::One was already covered by an earlier arm"),
        ("tier3_pattern_rest_not_last", routes + "task f(s: Shape) -> int {\n    when s {\n        Shape::Dot { .., x } -> give back x\n"
         "        _ -> give back 0\n    }\n    give back 2\n}\ntask main() -> int { give back f(Shape::Empty) }\n",
         "route pattern rest must come last"),
        # A when consumes a Move scrutinee, as Meiya says: the arm tests are
        # reads, but the subject copy moves the route out of s.
        ("tier3_pattern_scrutinee_moved", routes + "task main() -> int {\n    pilot s = Shape::Dot { x: 1, y: 2 }\n    when s {\n"
         "        Shape::Dot { x } -> say x\n        _ -> say 0\n    }\n    when s {\n        _ -> say 1\n    }\n    give back 0\n}\n",
         "Meiya carries that partial move across the CFG|s was moved"),
        # The bible's built-in `-> route` outcomes are not user routes yet.
        ("tier3_check_route_builtin", "task confess(c: int) -> route {\n    route BadEnd\n}\ntask main() -> int {\n    check route confess(5) {\n"
         "        TrueRoute -> give back 1\n        _ -> give back 0\n    }\n    give back 0\n}\n",
         "check route needs route source|got route"),
    )
    for stem, text, reason in rejected_cases:
        rejected_source = RUNTIME_BUILD_ROOT / f"{stem}.fk"
        rejected_source.write_text(text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / f"{stem}.ll"
        output.unlink(missing_ok=True)
        rejected = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(rejected_source), "-o", str(output), "--emit-llvm"],
            label=f"V4 build command: {stem}", timeout_seconds=180, memory_limit_mb=512,
        )
        if rejected.returncode == 0 or output.exists() or reason not in rejected.stdout + rejected.stderr:
            raise RuntimeError(f"V4 pattern case {stem} was not rejected with: {reason}\n{rejected.stdout}{rejected.stderr}")
    print(f"V4 native patterns: run=exact exit={NATIVE_PATTERNS_EXIT} layout-probes={probes} "
          f"targets={len(NATIVE_LAYOUT_TRIPLES)} rejections={len(rejected_cases)}")

NATIVE_C_WIDTHS_HELPERS = """int cw_add_int(int a, int b) { return a + b; }
unsigned cw_shift_uint(unsigned a) { return a << 4; }
long cw_negate_long(long a) { return -a; }
unsigned long cw_echo_ulong(unsigned long a) { return a; }
short cw_negate_short(short a) { return (short)-a; }
unsigned short cw_ushort_max(void) { return (unsigned short)65535; }
char cw_echo_char(char a) { return a; }
_Bool cw_char_is_negative(char a) { return a < 0; }
unsigned char cw_add_uchar(unsigned char a, unsigned char b) { return (unsigned char)(a + b); }
_Bool cw_is_even(int a) { return a % 2 == 0; }
_Bool cw_not(_Bool a) { return !a; }
long cw_mix(short a, int b, long c, unsigned char d, double e) { return a + b + c + d + (long)(e * 2.0); }
static int recorded;
void cw_record(int a) { recorded = a; }
int cw_recorded(void) { return recorded; }
"""

NATIVE_C_WIDTHS_PANIC = "FREAK V4: int to C int32 conversion out of range"


def native_c_widths_expected(triple: str) -> str:
    # Plain C char is unsigned only on AArch64 Linux among the four targets.
    negative = "no" if triple == "aarch64-unknown-linux-gnu" else "yes"
    return ("add_int=-2\nadd_int_min=-2147483648\nshift_uint=4294967280\nnegate_long=7\n"
            "echo_ulong=4294967295\nnegate_short=-1234\nushort_max=65535\necho_char=200\n"
            f"char_is_negative={negative}\nadd_uchar=44\nis_even_10=yes\nis_even_7=no\nnot_yes=no\n"
            "mix=69942\nrecorded=-2147483648\n")


def native_c_signatures(text: str, keyword: str) -> dict[str, str]:
    """Map each cw_* function to `ret(params)` with names and noundef removed."""
    signatures = {}
    for line in text.splitlines():
        match = re.match(rf"^{keyword} (?:dso_local )?(?:ccc )?(.*?) @(cw_\w+)\((.*?)\)", line)
        if not match:
            continue
        result, name, params = match.groups()
        cleaned = [re.sub(r" %\w+$", "", part.replace("noundef ", "")) for part in params.split(", ") if part]
        signatures[name] = result.replace("noundef ", "") + "(" + ", ".join(cleaned) + ")"
    return signatures


def check_v4_native_c_widths() -> None:
    """Tier 3 C widths: real C on the host, Clang's own signatures on all four targets."""
    from build_v4 import host_target, native_link_command

    clang = shutil.which("clang")
    source = V4_ROOT / "examples" / "c_widths_native.fk"
    helpers = RUNTIME_BUILD_ROOT / "tier3_c_widths_helpers.c"
    helpers.write_text(NATIVE_C_WIDTHS_HELPERS, encoding="utf-8")
    compared = 0
    for triple in NATIVE_LAYOUT_TRIPLES:
        module_path = RUNTIME_BUILD_ROOT / f"tier3_c_widths_{triple}.ll"
        module_path.unlink(missing_ok=True)
        emitted = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(module_path), "--emit-llvm", "--target", triple],
            label=f"V4 C widths module {triple}", timeout_seconds=180, memory_limit_mb=512,
        )
        if emitted.returncode != 0 or not module_path.exists():
            raise RuntimeError(f"V4 could not emit the C widths module for {triple}:\n{emitted.stdout}{emitted.stderr}")
        module = module_path.read_text(encoding="utf-8")
        oracle = run_with_heartbeat(
            [clang, f"--target={triple}", "-O0", "-w", "-S", "-emit-llvm", str(helpers), "-o", "-"],
            label=f"V4 C widths oracle {triple}", timeout_seconds=60, memory_limit_mb=512,
        )
        if oracle.returncode != 0:
            raise RuntimeError(f"Clang rejected the C widths helpers for {triple}:\n{oracle.stderr}")
        ours = native_c_signatures(module, "declare")
        theirs = native_c_signatures(oracle.stdout, "define")
        if len(theirs) != 14 or ours != theirs:
            raise RuntimeError(f"V4 C width signatures disagree with Clang on {triple}:\nV4: {ours}\nClang: {theirs}")
        compared += len(theirs)
        # Same plan text on every target; only the shims and declarations differ.
        assembled = run_with_heartbeat(
            [clang, f"--target={triple}", "-c", "-w", str(module_path), "-o", str(module_path.with_suffix(".o"))],
            label=f"V4 C widths object {triple}", timeout_seconds=60, memory_limit_mb=512,
        )
        if assembled.returncode != 0:
            raise RuntimeError(f"Clang rejected the V4 C widths module for {triple}:\n{assembled.stderr}")
    host = host_target()
    module_path = RUNTIME_BUILD_ROOT / f"tier3_c_widths_{host}.ll"
    executable = RUNTIME_BUILD_ROOT / ("tier3_c_widths.exe" if sys.platform == "win32" else "tier3_c_widths.native")
    executable.unlink(missing_ok=True)
    command = native_link_command(clang, module_path, executable)
    command.insert(command.index("-o"), str(helpers))
    linked = run_with_heartbeat(command, label="V4 C widths link", timeout_seconds=180, memory_limit_mb=1024)
    if linked.returncode != 0 or not executable.exists():
        raise RuntimeError(f"V4 C widths program did not link with real C:\n{linked.stdout}{linked.stderr}")
    ran = run_with_heartbeat([str(executable)], label="V4 native C widths execute", timeout_seconds=10, memory_limit_mb=128)
    if ran.returncode != 0 or ran.stdout.replace("\r\n", "\n") != native_c_widths_expected(host):
        raise RuntimeError(f"V4 native C widths printed the wrong output: exit={ran.returncode} stdout={ran.stdout!r}")
    # Any argument passes 3000000000 to a C int: checked, never truncated.
    failed = run_with_heartbeat([str(executable), "narrow"], label="V4 native C width check", timeout_seconds=10, memory_limit_mb=128)
    if failed.returncode != 1 or NATIVE_C_WIDTHS_PANIC not in failed.stderr or "recorded=" in failed.stdout:
        raise RuntimeError(f"V4 native C width narrowing was not checked: exit={failed.returncode} "
                           f"stdout={failed.stdout!r} stderr={failed.stderr!r}")
    rejected_cases = (
        # Extern task values and @extern_callback tasks with C widths are
        # native since the callback row (check_v4_native_c_abi runs them);
        # C widths in a FREAK task type stay fenced.
        ("tier3_c_width_freak_task_value", "task f(a: std::ffi::c_int) -> std::ffi::c_int { give back a }\n"
         "task main() -> int {\n pilot g = f\n give back 0\n}\n",
         "native C scalar ABI not yet supported: std::ffi::c_int"),
        ("tier3_c_width_wchar", "extern [C] { task f(a: std::ffi::wchar) -> std::ffi::c_int }\n"
         "task main() -> int { give back 0 }\n",
         "native C scalar ABI not yet supported: std::ffi::wchar"),
        ("tier3_c_width_pointer", "extern [C] { task f(a: *mut std::ffi::c_int) -> std::ffi::c_int }\n"
         "task main() -> int { give back 0 }\n",
         "native C scalar ABI not yet supported: std::ffi::c_int"),
        ("tier3_c_width_link_alias", "extern [C] {\n task f(a: std::ffi::c_int) -> std::ffi::c_int\n"
         " @link_name(\"f\")\n task g(a: std::ffi::c_isize) -> std::ffi::c_int\n}\n"
         "task main() -> int { give back f(1) + g(2) }\n",
         "native declaration symbol has incompatible signatures: @f"),
        ("tier3_c_width_reserved", "extern [C] {\n @link_name(\"freak_v4_cabi_check_int32\")\n"
         " task f(a: std::ffi::c_isize) -> std::ffi::c_isize\n}\ntask main() -> int { give back f(1) }\n",
         "native private runtime symbol conflict: @freak_v4_cabi_check_int32"),
    )
    for stem, text, reason in rejected_cases:
        rejected_source = RUNTIME_BUILD_ROOT / f"{stem}.fk"
        rejected_source.write_text(text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / f"{stem}.ll"
        output.unlink(missing_ok=True)
        rejected = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(rejected_source), "-o", str(output), "--emit-llvm"],
            label=f"V4 build command: {stem}", timeout_seconds=180, memory_limit_mb=512,
        )
        if rejected.returncode == 0 or output.exists() or reason not in rejected.stdout + rejected.stderr:
            raise RuntimeError(f"V4 C width case {stem} was not rejected with: {reason}\n{rejected.stdout}{rejected.stderr}")
    print(f"V4 native C widths: run=exact narrowing=checked clang-signatures={compared} "
          f"targets={len(NATIVE_LAYOUT_TRIPLES)} rejections={len(rejected_cases)}")


# Tier 3 C ABI rows: default argument promotions, native C variadic calls and
# callbacks over the C widths in both directions. The helpers are real C the
# program links with; the oracle is the same C boundary written as C, which
# Clang lowers for each target so its declarations, trampoline definitions and
# call sites (variadic and through function pointers) can be compared with
# the V4 module's.
NATIVE_C_ABI_HELPERS = """#include <stdarg.h>
#include <stddef.h>
#include <string.h>
static const char *const ca_texts[] = { "%d|%d|%c|%.2f|%.1f|%s", "tail", "iiudLUdp", "iiiiiiiiidddddddddd" };
static char ca_buf[64];
static unsigned char ca_mark;
const char *ca_text(int id) { return ca_texts[id]; }
char *ca_buffer(void) { return ca_buf; }
_Bool ca_buffer_is(int id) { return id == 0 && strcmp(ca_buf, "200|1|Z|2.25|2.5|tail") == 0; }
unsigned char *ca_marker(void) { return &ca_mark; }
long ca_kinds(const char *kinds, ...) {
    va_list ap;
    long long acc = 0;
    va_start(ap, kinds);
    for (const char *k = kinds; *k; ++k) {
        if (*k == 'i') acc = acc * 7 + va_arg(ap, int);
        else if (*k == 'u') acc = acc * 7 + (long long)va_arg(ap, unsigned int);
        else if (*k == 'L') acc += va_arg(ap, long long) / 1000;
        else if (*k == 'U') acc += (long long)(va_arg(ap, unsigned long long) % 1000003ULL);
        else if (*k == 'd') acc = acc * 2 + (long long)(va_arg(ap, double) * 8.0);
        else if (*k == 'p') acc += va_arg(ap, unsigned char *) == &ca_mark ? 100000 : -1;
    }
    va_end(ap);
    return (long)(acc % 2000000000LL);
}
short ca_sum_ints(short count, ...) {
    va_list ap;
    long long sum = 0;
    va_start(ap, count);
    for (short i = 0; i < count; ++i) sum += va_arg(ap, long long);
    va_end(ap);
    return (short)sum;
}
double ca_doubles(int count, ...) {
    va_list ap;
    double sum = 0.0;
    va_start(ap, count);
    for (int i = 0; i < count; ++i) sum += va_arg(ap, double);
    va_end(ap);
    return sum;
}
short ca_apply_short(short (*cb)(short), short v) { return cb(v); }
unsigned char ca_apply_uchar(unsigned char (*cb)(unsigned char), unsigned char v) { return cb(v); }
int ca_apply_char(int (*cb)(char), char v) { return cb(v); }
int ca_count_if(_Bool (*pred)(int), int limit) {
    int count = 0;
    for (int i = 0; i < limit; ++i) count += pred(i) ? 1 : 0;
    return count;
}
unsigned ca_apply_uint(unsigned (*cb)(unsigned), unsigned v) { return cb(v); }
long ca_apply_long(long (*cb)(long, unsigned long)) { return cb(-70000L, 3000000000UL); }
static short (*ca_saved)(short);
void ca_store(short (*cb)(short)) { ca_saved = cb; }
short (*ca_stored(void))(short) { return ca_saved; }
short ca_negate_short(short v) { return (short)-v; }
short (*ca_get_negate(void))(short) { return ca_negate_short; }
static _Bool ca_is_odd(int v) { return (v & 1) != 0; }
_Bool (*ca_get_is_odd(void))(int) { return ca_is_odd; }
"""

NATIVE_C_ABI_ORACLE = """#include <stdarg.h>
typedef __SIZE_TYPE__ size_t;
int snprintf(char *buf, size_t size, const char *format, ...);
const char *ca_text(int id);
char *ca_buffer(void);
_Bool ca_buffer_is(int id);
unsigned char *ca_marker(void);
long ca_kinds(const char *kinds, ...);
short ca_sum_ints(short count, ...);
double ca_doubles(int count, ...);
short ca_apply_short(short (*cb)(short), short v);
unsigned char ca_apply_uchar(unsigned char (*cb)(unsigned char), unsigned char v);
int ca_apply_char(int (*cb)(char), char v);
int ca_count_if(_Bool (*pred)(int), int limit);
unsigned ca_apply_uint(unsigned (*cb)(unsigned), unsigned v);
long ca_apply_long(long (*cb)(long, unsigned long));
void ca_store(short (*cb)(short));
short (*ca_stored(void))(short);
short (*ca_get_negate(void))(short);
_Bool (*ca_get_is_odd(void))(int);
short ca_negate_short(short v);
short __freak_callback_double_short(short v) { return v; }
unsigned char __freak_callback_bump_uchar(unsigned char v) { return v; }
int __freak_callback_char_code(char v) { return v; }
_Bool __freak_callback_is_multiple_of_three(int v) { return v != 0; }
unsigned __freak_callback_half_uint(unsigned v) { return v; }
long __freak_callback_mix_long(long a, unsigned long b) { return a + (long)b; }
short __freak_callback_overflow_short(short v) { return v; }
void oracle(unsigned char byte, _Bool truth, unsigned mark, float ratio, long long i, unsigned long long u, double d,
            short s, int n, unsigned un, char c) {
    snprintf(ca_buffer(), 64, ca_text(0), byte, truth, mark, ratio, d, ca_text(1));
    ca_buffer_is(n);
    ca_kinds(ca_text(n), byte, truth, mark, ratio, i, u, d, ca_marker());
    ca_kinds(ca_text(n), byte, byte, byte, byte, byte, byte, byte, byte, byte, d, d, d, d, d, d, d, d, d, d);
    ca_sum_ints(s, i, i, i);
    ca_doubles(n, ratio, d, d, d);
    ca_apply_short(__freak_callback_double_short, s);
    ca_apply_uchar(__freak_callback_bump_uchar, byte);
    ca_apply_char(__freak_callback_char_code, c);
    ca_count_if(__freak_callback_is_multiple_of_three, n);
    ca_apply_uint(__freak_callback_half_uint, un);
    ca_apply_long(__freak_callback_mix_long);
    ca_store(__freak_callback_double_short);
    ca_stored()(s);
    ca_get_negate()(s);
    ca_get_is_odd()(n);
    short (*direct)(short) = ca_negate_short;
    direct(s);
    ca_negate_short(s); /* the V4 declaration shim's own call */
}
"""

NATIVE_C_ABI_EXPECTED = (
    "snprintf=21\nsnprintf_text=yes\nkinds=-15861341\nstack_kinds=34866080\nsum_ints=-14993\ndoubles=800\n"
    "apply_short=-600\napply_uchar=250\napply_char=200\ncount_if=4\napply_uint=2000000000\napply_long=2930000\n"
    "stored=-8000\nnegate=-32768\nis_odd_7=yes\nis_odd_8=no\nextern_value=-1234\n"
)
NATIVE_C_ABI_PANIC = "FREAK V4: int to C int16 conversion out of range"


def native_c_abi_split_args(text: str) -> list[str]:
    parts, depth, start = [], 0, 0
    for index, char in enumerate(text):
        if char in "([{<":
            depth += 1
        elif char in ")]}>":
            depth -= 1
        elif char == "," and depth == 0:
            parts.append(text[start:index].strip())
            start = index + 1
    if text[start:].strip():
        parts.append(text[start:].strip())
    return parts


def native_c_abi_clean(part: str) -> str:
    part = re.sub(r"\b(noundef|dso_local|ccc)\b", "", part)
    return re.sub(r"\s+", " ", part).strip()


NATIVE_C_ABI_CALLEES = r"ca_\w+|snprintf"


def native_c_abi_facts(text: str, callees: str = NATIVE_C_ABI_CALLEES) -> set[tuple[str, str, str]]:
    """Every C boundary in a module: declarations and trampoline definitions
    as (kind, name, ret(params)), and C call sites as ("call", callee, shape)
    with values removed; calls through a pointer have callee "*". callees is
    the regex of the C symbols the module and its oracle share."""
    facts = set()
    for line in text.splitlines():
        declared = re.match(r"^(declare|define) (.*?) @(" + callees + r"|__freak_callback_\w+)\((.*?)\)", line)
        if declared:
            kind, result, name, params = declared.groups()
            if kind == "declare" and name.startswith("__freak_callback_"):
                continue
            if kind == "define" and not name.startswith("__freak_callback_"):
                continue
            cleaned = [native_c_abi_clean(re.sub(r" %[\w.]+$", "", part)) for part in native_c_abi_split_args(params)]
            facts.add((kind, name, native_c_abi_clean(result) + "(" + ", ".join(cleaned) + ")"))
            continue
        called = re.search(r"\bcall (.*?) (@(?:" + callees + r")|%[\w.]+)\((.*)\)", line)
        if not called:
            continue
        result, callee, args = called.groups()
        shapes = [native_c_abi_clean(" ".join(native_c_abi_clean(arg).split(" ")[:-1])) for arg in native_c_abi_split_args(args)]
        facts.add(("call", "*" if callee.startswith("%") else callee[1:], native_c_abi_clean(result) + " (" + ", ".join(shapes) + ")"))
    return facts


def check_v4_native_c_abi() -> None:
    """Tier 3 C ABI rows: real C on the host, Clang's own lowering on all four targets."""
    from build_v4 import host_target, native_link_command

    clang = shutil.which("clang")
    source = V4_ROOT / "examples" / "c_abi_native.fk"
    helpers = RUNTIME_BUILD_ROOT / "tier3_c_abi_helpers.c"
    helpers.write_text(NATIVE_C_ABI_HELPERS, encoding="utf-8")
    oracle_source = RUNTIME_BUILD_ROOT / "tier3_c_abi_oracle.c"
    oracle_source.write_text(NATIVE_C_ABI_ORACLE, encoding="utf-8")
    compared = 0
    for triple in NATIVE_LAYOUT_TRIPLES:
        module_path = RUNTIME_BUILD_ROOT / f"tier3_c_abi_{triple}.ll"
        module_path.unlink(missing_ok=True)
        emitted = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(module_path), "--emit-llvm", "--target", triple],
            label=f"V4 C ABI module {triple}", timeout_seconds=180, memory_limit_mb=512,
        )
        if emitted.returncode != 0 or not module_path.exists():
            raise RuntimeError(f"V4 could not emit the C ABI module for {triple}:\n{emitted.stdout}{emitted.stderr}")
        module = module_path.read_text(encoding="utf-8")
        oracle = run_with_heartbeat(
            [clang, f"--target={triple}", "-O0", "-w", "-S", "-emit-llvm", str(oracle_source), "-o", "-"],
            label=f"V4 C ABI oracle {triple}", timeout_seconds=60, memory_limit_mb=512,
        )
        if oracle.returncode != 0:
            raise RuntimeError(f"Clang rejected the C ABI oracle for {triple}:\n{oracle.stderr}")
        ours = native_c_abi_facts(module)
        theirs = native_c_abi_facts(oracle.stdout)
        # 19 declarations, 7 trampolines, and the distinct call shapes.
        if sum(1 for fact in theirs if fact[0] != "call") != 26 or ours != theirs:
            raise RuntimeError(f"V4 C ABI boundaries disagree with Clang on {triple}:\n"
                               f"V4 only: {sorted(ours - theirs)}\nClang only: {sorted(theirs - ours)}")
        # Varargs keep LLVM's variadic call form on every target, which is
        # what lets the backend apply Apple arm64 stack varargs and the Win64
        # floating-vararg register duplication.
        if not any(fact[0] == "call" and fact[2].startswith("i32 (ptr, i64, ptr, ...)") for fact in ours):
            raise RuntimeError(f"V4 snprintf call lost the variadic call form on {triple}")
        compared += len(theirs)
        assembled = run_with_heartbeat(
            [clang, f"--target={triple}", "-c", "-w", str(module_path), "-o", str(module_path.with_suffix(".o"))],
            label=f"V4 C ABI object {triple}", timeout_seconds=60, memory_limit_mb=512,
        )
        if assembled.returncode != 0:
            raise RuntimeError(f"Clang rejected the V4 C ABI module for {triple}:\n{assembled.stderr}")
    host = host_target()
    module_path = RUNTIME_BUILD_ROOT / f"tier3_c_abi_{host}.ll"
    executable = RUNTIME_BUILD_ROOT / ("tier3_c_abi.exe" if sys.platform == "win32" else "tier3_c_abi.native")
    executable.unlink(missing_ok=True)
    command = native_link_command(clang, module_path, executable)
    command.insert(command.index("-o"), str(helpers))
    linked = run_with_heartbeat(command, label="V4 C ABI link", timeout_seconds=180, memory_limit_mb=1024)
    if linked.returncode != 0 or not executable.exists():
        raise RuntimeError(f"V4 C ABI program did not link with real C:\n{linked.stdout}{linked.stderr}")
    ran = run_with_heartbeat([str(executable)], label="V4 native C ABI execute", timeout_seconds=10, memory_limit_mb=128)
    if ran.returncode != 0 or ran.stdout.replace("\r\n", "\n") != NATIVE_C_ABI_EXPECTED:
        raise RuntimeError(f"V4 native C ABI printed the wrong output: exit={ran.returncode} stdout={ran.stdout!r}")
    # One argument: a callback result too wide for C short; two: an argument
    # through an extern function pointer. Both are checked, never truncated.
    for arguments in (["callback"], ["pointer", "arg"]):
        failed = run_with_heartbeat([str(executable), *arguments], label="V4 native C ABI check", timeout_seconds=10, memory_limit_mb=128)
        if failed.returncode != 1 or NATIVE_C_ABI_PANIC not in failed.stderr or "unreachable=" in failed.stdout \
                or failed.stdout.replace("\r\n", "\n") != NATIVE_C_ABI_EXPECTED:
            raise RuntimeError(f"V4 native C ABI narrowing was not checked for {arguments}: exit={failed.returncode} "
                               f"stdout={failed.stdout!r} stderr={failed.stderr!r}")
    rejected_cases = (
        ("tier3_c_abi_variadic_callback", "@extern_callback(\"C\")\ntask cb(a: std::ffi::c_int, args: ...) -> std::ffi::c_int { give back a }\n"
         "task main() -> int { give back 0 }\n", "@extern_callback tasks cannot be variadic"),
        ("tier3_c_abi_variadic_value", "extern [C] { task f(n: std::ffi::c_isize, args: ...) -> std::ffi::c_isize }\n"
         "task main() -> int {\n pilot p = f\n give back p(1, 2)\n}\n",
         "native C variadic function pointers are not yet supported: f"),
        ("tier3_c_abi_variadic_pointer_type", "extern [C] { task f(cb: extern [C] task(n: std::ffi::c_int, args: ...) -> std::ffi::c_int) -> void }\n"
         "task main() -> int { give back 0 }\n", "native C variadic function pointers are not yet supported"),
        ("tier3_c_abi_word_vararg", "extern [C] { task f(n: std::ffi::c_int, args: ...) -> std::ffi::c_int }\n"
         "task main() -> int { give back f(1, \"text\") }\n", "variadic call argument is not C vararg safe"),
        ("tier3_c_abi_tuple_vararg", "extern [C] { task f(n: std::ffi::c_int, args: ...) -> std::ffi::c_int }\n"
         "task main() -> int { give back f(1, (1, 2)) }\n", "variadic call argument is not C vararg safe"),
        ("tier3_c_abi_freak_task_type", "task g(cb: task(v: std::ffi::c_int) -> std::ffi::c_int) -> int { give back 0 }\n"
         "task main() -> int { give back 0 }\n", "native C scalar ABI not yet supported: std::ffi::c_int"),
        ("tier3_c_abi_alias_callback", "alias Cb = extern [C] task(v: std::ffi::c_short) -> std::ffi::c_short\n"
         "task use(cb: Cb) -> int { give back cb(5) }\ntask main() -> int { give back 0 }\n",
         "native C scalar ABI not yet supported: std::ffi::c_short"),
        ("tier3_c_abi_pointee_callback", "extern [C] { task f(cb: extern [C] task(v: *mut std::ffi::c_int) -> std::ffi::c_int) -> void }\n"
         "task main() -> int { give back 0 }\n", "native C scalar ABI not yet supported: std::ffi::c_int"),
        ("tier3_c_abi_wchar_callback", "extern [C] { task f(cb: extern [C] task(v: std::ffi::wchar) -> std::ffi::c_int) -> void }\n"
         "task main() -> int { give back 0 }\n", "native C scalar ABI not yet supported: std::ffi::wchar"),
        ("tier3_c_abi_bool_callback", "extern [C] { task f(cb: extern [C] task(v: bool) -> std::ffi::c_int) -> void }\n"
         "task main() -> int { give back 0 }\n", "callback parameter type is not FFI-safe"),
        ("tier3_c_abi_width_mismatch", "extern [C] { task f(cb: extern [C] task(v: std::ffi::c_int) -> std::ffi::c_int) -> void }\n"
         "@extern_callback(\"C\")\ntask wide(v: std::ffi::c_isize) -> std::ffi::c_isize { give back v }\n"
         "task main() -> int {\n f(wide)\n give back 0\n}\n", "callback value must use extern ABI"),
    )
    for stem, text, reason in rejected_cases:
        rejected_source = RUNTIME_BUILD_ROOT / f"{stem}.fk"
        rejected_source.write_text(text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / f"{stem}.ll"
        output.unlink(missing_ok=True)
        rejected = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(rejected_source), "-o", str(output), "--emit-llvm"],
            label=f"V4 build command: {stem}", timeout_seconds=180, memory_limit_mb=512,
        )
        if rejected.returncode == 0 or output.exists() or reason not in rejected.stdout + rejected.stderr:
            raise RuntimeError(f"V4 C ABI case {stem} was not rejected with: {reason}\n{rejected.stdout}{rejected.stderr}")
    print(f"V4 native C ABI: run=exact narrowing=checked clang-facts={compared} "
          f"targets={len(NATIVE_LAYOUT_TRIPLES)} rejections={len(rejected_cases)}")


# Tier 3 C ABI: word bytes at a C boundary. A `lend s: word` parameter of an
# extern declaration is the pair (const char*, size_t); the oracle is the
# same boundary written as C, which Clang lowers on every target so the
# declarations and the shims' C call sites can be compared with V4's (size_t
# is Clang's own __SIZE_TYPE__ there). The helpers are real C.
NATIVE_C_WORDS_ORACLE = """typedef __SIZE_TYPE__ size_t;
size_t cw_count_byte(const char *bytes, size_t length, int byte);
unsigned cw_checksum(const char *bytes, size_t length);
_Bool cw_same(const char *left, size_t left_length, const char *right, size_t right_length);
int cw_byte_at(const char *bytes, size_t length, size_t index);
long cw_lengths(long scale, const char *first, size_t first_length, const char *second, size_t second_length);
void cw_remember(const char *bytes, size_t length);
_Bool cw_is_remembered(const char *bytes, size_t length);
short cw_short_len(const char *bytes, size_t length);
void oracle(const char *p, size_t n, int c, long l) {
    cw_count_byte(p, n, c);
    cw_checksum(p, n);
    cw_same(p, n, p, n);
    cw_byte_at(p, n, n);
    cw_lengths(l, p, n, p, n);
    cw_remember(p, n);
    cw_is_remembered(p, n);
    cw_short_len(p, n);
}
"""

NATIVE_C_WORDS_EXPECTED = (
    "count_l=3\ngreeting=hello world\nlengths=11006\nscalars=5\nlead_bytes=1\nbyte_3=195\nnul_len=3\nnul_count=1\n"
    "same_storage=yes\ncopy_storage=no\ncopy_bytes=yes\nother_bytes=no\nempty_len=11\ncallsign_k=1 rank=2\nsquad_a=1\n"
    "checksum_total=100320\nchecksum=3582672807\nmoved=Valkyrie\nshort_len=-11\n"
)

# Named refusals around word bytes at a C boundary: (stem, source, reason).
NATIVE_C_WORDS_REJECTED = (
    ("tier3_c_word_by_value", "extern [C] { task f(s: word) -> std::ffi::c_int }\ntask main() -> int { give back 0 }\n",
     "f.s uses word; that is a FREAK string fat pointer, not a C char*. Declare it as a lend word parameter"),
    ("tier3_c_word_lend_mut", "extern [C] { task f(lend mut s: word) -> std::ffi::c_int }\ntask main() -> int { give back 0 }\n",
     "f.s is lend mut word; C must not write the bytes a FREAK word owns"),
    ("tier3_c_word_return", "extern [C] { task f() -> word }\ntask main() -> int { give back 0 }\n",
     "f return uses word; that is a FREAK string fat pointer"),
    ("tier3_c_word_alias", "alias Text = word\nextern [C] { task f(lend s: Text) -> std::ffi::c_int }\ntask main() -> int { give back 0 }\n",
     "extern parameter type is not FFI-safe"),
    ("tier3_c_word_callback", "@extern_callback(\"C\")\ntask cb(lend s: word) -> std::ffi::c_int { give back 0 }\n"
     "task main() -> int { give back 0 }\n", "cb.s lends a word to a callback"),
    ("tier3_c_word_callback_type", "extern [C] { task f(cb: extern [C] task(lend s: word) -> std::ffi::c_int) -> void }\n"
     "task main() -> int { give back 0 }\n", "callback parameter type is not FFI-safe"),
    ("tier3_c_word_variadic", "extern [C] { task f(lend s: word, args: ...) -> std::ffi::c_int }\n"
     "task main() -> int {\n    pilot w = \"hi\"\n    give back f(lend w, 1)\n}\n",
     "native lend word parameters of variadic C declarations are not yet supported: f"),
    ("tier3_c_word_task_value", "extern [C] { task f(lend s: word) -> std::ffi::c_int }\n"
     "task main() -> int {\n    pilot p = f\n    give back 0\n}\n", "native word task pointer contracts are not yet supported"),
    ("tier3_c_word_needs_lend", "extern [C] { task f(lend s: word) -> std::ffi::c_size }\n"
     "task main() -> int {\n    pilot w = \"hi\"\n    give back f(w)\n}\n", "borrowed call argument needs lend"),
    ("tier3_c_word_temporary", "extern [C] { task f(lend s: word) -> std::ffi::c_size }\n"
     "task main() -> int { give back f(lend \"abc\") }\n", "lend source must be a place"),
    ("tier3_c_word_after_move", "extern [C] { task f(lend s: word) -> std::ffi::c_size }\ntask eat(w: word) -> int { give back 0 }\n"
     "task main() -> int {\n    pilot w = \"hi\"\n    eat(w)\n    give back f(lend w)\n}\n", "w was moved"),
    ("tier3_c_word_rewrite_lent", "extern [C] { task f(lend s: word) -> std::ffi::c_int }\n"
     "task main() -> int {\n    pilot mut w = \"hi\"\n    pilot r = lend w\n    w = \"yo\"\n    give back f(r)\n}\n",
     "Meiya refuses this rewrite while the value is borrowed"),
)


def check_v4_native_c_words() -> None:
    """Tier 3 C ABI: lend word extern parameters as (const char*, size_t), checked against Clang."""
    from build_v4 import host_target, native_link_command

    clang = shutil.which("clang")
    source = V4_ROOT / "examples" / "c_words_native.fk"
    helpers = V4_ROOT / "examples" / "c_words_native_helpers.c"
    oracle_source = RUNTIME_BUILD_ROOT / "tier3_c_words_oracle.c"
    oracle_source.write_text(NATIVE_C_WORDS_ORACLE, encoding="utf-8")
    compared = 0
    for triple in NATIVE_LAYOUT_TRIPLES:
        module_path = RUNTIME_BUILD_ROOT / f"tier3_c_words_{triple}.ll"
        module_path.unlink(missing_ok=True)
        emitted = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(module_path), "--emit-llvm", "--target", triple],
            label=f"V4 C words module {triple}", timeout_seconds=180, memory_limit_mb=512,
        )
        if emitted.returncode != 0 or not module_path.exists():
            raise RuntimeError(f"V4 could not emit the C words module for {triple}:\n{emitted.stdout}{emitted.stderr}")
        module = module_path.read_text(encoding="utf-8")
        oracle = run_with_heartbeat(
            [clang, f"--target={triple}", "-O0", "-w", "-S", "-emit-llvm", str(oracle_source), "-o", "-"],
            label=f"V4 C words oracle {triple}", timeout_seconds=60, memory_limit_mb=512,
        )
        if oracle.returncode != 0:
            raise RuntimeError(f"Clang rejected the C words oracle for {triple}:\n{oracle.stderr}")
        ours = native_c_abi_facts(module, r"cw_\w+")
        theirs = native_c_abi_facts(oracle.stdout, r"cw_\w+")
        # Eight declarations and eight call shapes, every word a (ptr, size_t) pair.
        if sum(1 for fact in theirs if fact[0] == "declare") != 8 or ours != theirs:
            raise RuntimeError(f"V4 C word boundaries disagree with Clang on {triple}:\n"
                               f"V4 only: {sorted(ours - theirs)}\nClang only: {sorted(theirs - ours)}")
        compared += len(theirs)
        # Each shim lends the caller's storage: no word is built, cloned or
        # dropped on the way to C, and C never needs a terminator.
        shims = re.findall(r'^define internal [^\n]*@"freak\.cabi\.cw_\w+"\(.*?^\}', module, re.MULTILINE | re.DOTALL)
        if len(shims) != 8 or any(re.search(r"@freak_v4_word_(?:from_bytes|clone|concat|drop)\b|@strlen\b", shim) for shim in shims) \
                or any("@freak_v4_word_bytes(" not in shim or "inttoptr i64 %a" not in shim for shim in shims):
            raise RuntimeError(f"V4 C word shims do not lend the word's own bytes on {triple}")
        assembled = run_with_heartbeat(
            [clang, f"--target={triple}", "-c", "-w", str(module_path), "-o", str(module_path.with_suffix(".o"))],
            label=f"V4 C words object {triple}", timeout_seconds=60, memory_limit_mb=512,
        )
        if assembled.returncode != 0:
            raise RuntimeError(f"Clang rejected the V4 C words module for {triple}:\n{assembled.stderr}")
    host = host_target()
    module_path = RUNTIME_BUILD_ROOT / f"tier3_c_words_{host}.ll"
    executable = RUNTIME_BUILD_ROOT / ("tier3_c_words.exe" if sys.platform == "win32" else "tier3_c_words.native")
    executable.unlink(missing_ok=True)
    command = native_link_command(clang, module_path, executable)
    command.insert(command.index("-o"), str(helpers))
    linked = run_with_heartbeat(command, label="V4 C words link", timeout_seconds=180, memory_limit_mb=1024)
    if linked.returncode != 0 or not executable.exists():
        raise RuntimeError(f"V4 C words program did not link with real C:\n{linked.stdout}{linked.stderr}")
    ran = run_with_heartbeat([str(executable)], label="V4 native C words execute", timeout_seconds=10, memory_limit_mb=128)
    if ran.returncode != 0 or ran.stdout.replace("\r\n", "\n") != NATIVE_C_WORDS_EXPECTED:
        raise RuntimeError(f"V4 native C words printed the wrong output: exit={ran.returncode} stdout={ran.stdout!r}")
    for stem, text, reason in NATIVE_C_WORDS_REJECTED:
        rejected_source = RUNTIME_BUILD_ROOT / f"{stem}.fk"
        rejected_source.write_text(text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / f"{stem}.ll"
        output.unlink(missing_ok=True)
        rejected = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(rejected_source), "-o", str(output), "--emit-llvm"],
            label=f"V4 build command: {stem}", timeout_seconds=180, memory_limit_mb=512,
        )
        if rejected.returncode == 0 or output.exists() or reason not in rejected.stdout + rejected.stderr:
            raise RuntimeError(f"V4 C words case {stem} was not rejected with: {reason}\n{rejected.stdout}{rejected.stderr}")
    print(f"V4 native C words: run=exact clang-facts={compared} targets={len(NATIVE_LAYOUT_TRIPLES)} "
          f"rejections={len(NATIVE_C_WORDS_REJECTED)}")


def check_v4_build_command() -> None:
    from build_v4 import bootstrap, host_target

    compiler = bootstrap(shutil.which("clang"))
    source_paths = checked_source_fixture_paths()
    for arguments in ([], [source_paths[0]], [source_paths[2], host_target()], [source_paths[3], host_target()]):
        rejected = run_with_heartbeat(
            [str(compiler), *arguments], label="V4 bootstrap source rejection",
            timeout_seconds=10, memory_limit_mb=64,
        )
        if (
            rejected.returncode != 0 or rejected.stderr
            or "v4-source-read-error=" not in rejected.stdout
            or "v4-aborted-after=source" not in rejected.stdout
            or "v4-build-stage=" in rejected.stdout or "@@V4-MODULE" in rejected.stdout
        ):
            raise RuntimeError(f"V4 bootstrap published a failed source:\n{rejected.stdout}{rejected.stderr}")
    library_source = RUNTIME_BUILD_ROOT / "llvm_no_main_library.fk"
    library_source.write_text("task helper() -> int { give back 7 }\n", encoding="utf-8")
    warning_source = RUNTIME_BUILD_ROOT / "llvm_warning_only.fk"
    warning_source.write_text(
        'extern [C] {\n task _Unwind_Resume(exception: *mut std::ffi::c_void) -> void\n}\n'
        'task main() -> int { give back 42 }\n', encoding="utf-8",
    )
    error_source = RUNTIME_BUILD_ROOT / "llvm_error.fk"
    error_source.write_text('task main() -> int { give back "wrong" }\n', encoding="utf-8")
    root_source = RUNTIME_BUILD_ROOT / "llvm_root_error.fk"
    root_source.write_text('pilot global = 0\n', encoding="utf-8")
    say_error_source = RUNTIME_BUILD_ROOT / "llvm_say_error.fk"
    say_error_source.write_text('task main() -> int { say 42u\n give back 0 }\n', encoding="utf-8")
    word_error_source = RUNTIME_BUILD_ROOT / "llvm_word_error.fk"
    word_error_source.write_text(
        'task make() -> word { give back "owned" }\n'
        'task main() -> int { pilot callback: task() -> word = make\n'
        ' pilot text = callback()\n say text\n give back 0 }\n', encoding="utf-8",
    )
    main_error_source = RUNTIME_BUILD_ROOT / "llvm_main_error.fk"
    main_error_source.write_text('task main(value: int) -> int { give back value }\n', encoding="utf-8")
    runtime_say_error = RUNTIME_BUILD_ROOT / "llvm_runtime_say_error.fk"
    runtime_say_error.write_text(
        'extern [C] {\n @link_name("freak_llvm_say")\n task shadow_say(value: std::ffi::c_isize) -> std::ffi::c_isize\n}\n'
        'task main() -> int { say "hello"\n give back 0 }\n', encoding="utf-8",
    )
    runtime_setup_error = RUNTIME_BUILD_ROOT / "llvm_runtime_setup_error.fk"
    runtime_setup_error.write_text(
        'extern [C] { task freak_llvm_setup_args(argc: std::ffi::c_isize) -> void }\n'
        'task main() -> int { give back 0 }\n', encoding="utf-8",
    )
    executable = RUNTIME_BUILD_ROOT / ("llvm_warning_only.exe" if sys.platform == "win32" else "llvm_warning_only.native")
    for source, output, expected_success, abort_stage in (
        (warning_source, executable, True, None),
        (error_source, RUNTIME_BUILD_ROOT / "llvm_error.ll", False, "mir"),
        (root_source, RUNTIME_BUILD_ROOT / "llvm_root_error.ll", False, "parse"),
        (say_error_source, RUNTIME_BUILD_ROOT / "llvm_say_error.ll", False, "mir"),
        (word_error_source, RUNTIME_BUILD_ROOT / "llvm_word_error.ll", False, "codegen"),
        (main_error_source, RUNTIME_BUILD_ROOT / "llvm_main_error.ll", False, "entry"),
        (runtime_say_error, RUNTIME_BUILD_ROOT / "llvm_runtime_say_error.ll", False, "codegen"),
        (runtime_setup_error, RUNTIME_BUILD_ROOT / "llvm_runtime_setup_error.ll", False, "codegen"),
        (Path(source_paths[0]), RUNTIME_BUILD_ROOT / "llvm_empty_source.ll", False, "codegen"),
        (library_source, RUNTIME_BUILD_ROOT / "llvm_no_main_library.ll", False, "codegen"),
        (Path(source_paths[2]), RUNTIME_BUILD_ROOT / "llvm_missing_source.ll", False, None),
        (Path(source_paths[3]), RUNTIME_BUILD_ROOT / "llvm_directory_source.ll", False, None),
    ):
        output.unlink(missing_ok=True)
        command = [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(output)]
        if not expected_success:
            command.append("--emit-llvm")
        result = run_with_heartbeat(command, label="V4 build command", timeout_seconds=180, memory_limit_mb=512)
        if (result.returncode == 0) != expected_success or output.exists() != expected_success:
            raise RuntimeError(f"V4 build command rejection mismatch:\n{result.stdout}{result.stderr}")
        reasons = {
            say_error_source: "say value has no supported display contract",
            word_error_source: "native word task pointer contracts are not yet supported",
            main_error_source: "main must not declare parameters",
            runtime_say_error: "native runtime declaration conflicts with @freak_llvm_say",
            runtime_setup_error: "native runtime declaration conflicts with @freak_llvm_setup_args",
            Path(source_paths[0]): "native build requires task main",
            library_source: "native build requires task main",
            Path(source_paths[2]): "source file does not exist",
            Path(source_paths[3]): "source file does not exist",
        }
        if source in reasons and reasons[source] not in result.stdout + result.stderr:
            raise RuntimeError(f"V4 build rejected input without the expected reason: {reasons[source]}")
        if abort_stage and f"v4-aborted-after={abort_stage}" not in result.stdout + result.stderr:
            raise RuntimeError("V4 build did not stop at the stage reporting errors")
        if abort_stage == "parse" and "v4-build-stage=hir" in result.stdout + result.stderr:
            raise RuntimeError("V4 build lowered unsupported root syntax past parsing")
        if expected_success and "v4-errors=0" not in result.stdout:
            raise RuntimeError("warning-only V4 build did not report zero errors")
        if expected_success and "extern import unwinds across the FFI boundary" not in result.stdout:
            raise RuntimeError("warning-only V4 build did not retain its unwinder warning")
    # Default panic=unwind ends the main sortie as panicked: output written
    # before the panic survives, stderr carries the exact report, status 101.
    panic_source = RUNTIME_BUILD_ROOT / "llvm_panic_unwind.fk"
    panic_source.write_text(
        'task check(n: int) -> int {\n if n > 2 { panic("too big: " + word_from_int(n)) }\n give back n\n}\n'
        'task main() -> int {\n say "before"\n pilot a = check(1)\n pilot b = check(5)\n say "after"\n give back a + b\n}\n',
        encoding="utf-8",
    )
    panic_executable = RUNTIME_BUILD_ROOT / ("llvm_panic_unwind.exe" if sys.platform == "win32" else "llvm_panic_unwind.native")
    panic_executable.unlink(missing_ok=True)
    built = run_with_heartbeat(
        [sys.executable, str(V4_ROOT / "build_v4.py"), str(panic_source), "-o", str(panic_executable)],
        label="V4 build command: default panic", timeout_seconds=180, memory_limit_mb=512,
    )
    if built.returncode != 0 or not panic_executable.exists():
        raise RuntimeError(f"V4 default panic policy rejected a panicking program:\n{built.stdout}{built.stderr}")
    panicked = run_with_heartbeat([str(panic_executable)], label="V4 default panic execute", timeout_seconds=10, memory_limit_mb=128)
    if (panicked.returncode, panicked.stdout.replace("\r\n", "\n"), panicked.stderr) != (101, "before\n", "PANIC: too big: 5\n"):
        raise RuntimeError(f"V4 default panic did not end main as panicked: exit={panicked.returncode} stdout={panicked.stdout!r} stderr={panicked.stderr!r}")
    print("V4 default panic: main-sortie unwind exit=101")
    check_v4_native_shapes()
    # Exercise the actual bootstrap/tool boundary as well as plan-level facts:
    # rejected body/entry symbols and cross-target conventions publish no LLVM.
    contract_cases = [
        (
            "declaration_alias", host_target(),
            'extern [C] {\n @link_name("native_same")\n task first() -> std::ffi::c_isize\n'
            ' @link_name("native_same")\n task second(value: std::ffi::c_isize) -> std::ffi::c_isize\n}\n'
            'task main() -> int { give back first() }\n',
            "native declaration symbol has incompatible signatures: @native_same",
        ),
        (
            "literal_alias", host_target(),
            'extern [C] {\n @link_name(".str.0.0")\n task outside() -> std::ffi::c_isize\n}\n'
            'task main() -> int { say "literal"\n give back 0 }\n',
            'native literal global symbol conflicts with callable symbol: @".str.0.0"',
        ),
        (
            # Direct extern declarations lower C widths (check_v4_native_c_widths);
            # FREAK-side signatures and locals keep the named fence.
            "c_int_width", host_target(),
            'task echo_c_int(value: std::ffi::c_int) -> std::ffi::c_int { give back value }\n'
            'task main() -> int { if echo_c_int(0 - 1) < 0 { give back 42 }\n give back 7 }\n',
            "native C scalar ABI not yet supported: std::ffi::c_int",
        ),
        (
            "c_long_width", host_target(),
            'extern [C] { task outside() -> std::ffi::c_isize }\n'
            'task main() -> int {\n pilot value: std::ffi::c_long = outside()\n give back value\n}\n',
            "native C scalar ABI not yet supported: std::ffi::c_long",
        ),
        (
            "c_width_cast", host_target(),
            'extern [C] { task probe_ptr() -> *mut tiny }\n'
            'task main() -> int {\n pilot p = probe_ptr()\n'
            ' trust me "test raw C width cast" on my honor as .ace {\n'
            '  pilot value = p.cast<std::ffi::c_int>()\n }\n give back 42\n}\n',
            "native C scalar ABI not yet supported: std::ffi::c_int",
        ),
        (
            # Variadic extern calls are native (check_v4_native_c_abi); a
            # variadic extern used as a task value is not.
            "c_variadic_value", host_target(),
            'extern [C] { task outside(value: std::ffi::c_isize, args: ...) -> std::ffi::c_isize }\n'
            'task main() -> int {\n pilot f = outside\n give back f(1, 2)\n}\n',
            "native C variadic function pointers are not yet supported: outside",
        ),
        (
            "target_cc", "aarch64-apple-darwin",
            'extern [stdcall] { task outside() -> std::ffi::c_isize }\n'
            'task main() -> int { give back outside() }\n',
            "native target calling convention not supported: stdcall for aarch64-apple-darwin",
        ),
        (
            "body_symbol", host_target(),
            'shape A { marker: int }\n'
            'impl A { task b() -> int { give back 42 } }\n'
            'extern [C] {\n @link_name("A::b")\n task outside() -> std::ffi::c_isize\n}\n'
            'task main() -> int { give back outside() }\n',
            'native body symbol conflicts with explicit ABI declaration: @"A::b"',
        ),
        (
            "callback_symbol", host_target(),
            '@extern_callback("C")\n'
            'task callback() -> std::ffi::c_isize { give back 42 }\n'
            'extern [C] {\n @link_name("__freak_callback_callback")\n task outside() -> std::ffi::c_isize\n}\n'
            'task main() -> int { give back outside() }\n',
            "native body symbol conflicts with explicit ABI declaration: @__freak_callback_callback",
        ),
        (
            "callback_body", host_target(),
            '@extern_callback("C")\n'
            'task callback() -> std::ffi::c_isize { give back 42 }\n'
            'task __freak_callback_callback() -> int { give back 7 }\n'
            'task main() -> int { give back 0 }\n',
            "native body symbol has multiple definitions: @__freak_callback_callback",
        ),
    ]
    contract_cases.extend([
        ("ordinary_same_impl", host_target(),
         'shape A { marker: int }\nimpl A {\n task value() -> int { give back 2 }\n task value() -> int { give back 3 }\n}\ntask main() -> int { give back 42 }\n',
         'native body symbol has multiple definitions: @"A::value"'),
        ("ordinary_two_impls", host_target(),
         'shape A { marker: int }\nimpl A { task value() -> int { give back 2 } }\nimpl A { task value() -> int { give back 3 } }\ntask main() -> int { give back 42 }\n',
         'native body symbol has multiple definitions: @"A::value"'),
        ("ordinary_qualified_and_impl", host_target(),
         'shape A { marker: int }\ntask A::value() -> int { give back 2 }\nimpl A { task value() -> int { give back 3 } }\ntask main() -> int { give back 42 }\n',
         'native body symbol has multiple definitions: @"A::value"'),
    ])
    for label, symbol in (("public_entry", "main"), ("private_entry", "freak.user.main")):
        contract_cases.append((
            label, host_target(),
            f'extern [C] {{\n @link_name("{symbol}")\n task outside() -> std::ffi::c_isize\n}}\n'
            'task main() -> int { give back outside() }\n',
            "native entry symbol conflicts with explicit ABI declaration",
        ))
    for label, target, source_text, reason in contract_cases:
        source = RUNTIME_BUILD_ROOT / f"llvm_contract_{label}.fk"
        output = RUNTIME_BUILD_ROOT / f"llvm_contract_{label}.ll"
        source.write_text(source_text, encoding="utf-8")
        output.unlink(missing_ok=True)
        raw = run_with_heartbeat(
            [str(compiler), str(source), target], label=f"V4 native contract: {label}",
            timeout_seconds=30, memory_limit_mb=64,
        )
        if (
            raw.returncode != 0 or raw.stderr or reason not in raw.stdout
            or "v4-aborted-after=codegen" not in raw.stdout or "@@V4-MODULE" in raw.stdout
        ):
            raise RuntimeError(f"V4 bootstrap published an invalid native contract:\n{raw.stdout}{raw.stderr}")
        rejected = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(output),
             "--emit-llvm", "--target", target],
            label=f"V4 native contract CLI: {label}", timeout_seconds=180, memory_limit_mb=512,
        )
        if (
            rejected.returncode == 0 or output.exists()
            or reason not in rejected.stdout + rejected.stderr
            or "@@V4-MODULE" in rejected.stdout + rejected.stderr
        ):
            raise RuntimeError(f"V4 CLI native-contract rejection mismatch:\n{rejected.stdout}{rejected.stderr}")
        print(f"V4 native contract rejection: {label} named=true no-module=true no-output=true")
    executed = run_with_heartbeat([str(executable)], label="V4 warning-only execute", timeout_seconds=10, memory_limit_mb=128)
    if executed.returncode != 42 or executed.stdout or executed.stderr:
        raise RuntimeError("warning-only V4 build did not execute correctly")
    hello = RUNTIME_BUILD_ROOT / ("hello_world.exe" if sys.platform == "win32" else "hello_world.native")
    hello.unlink(missing_ok=True)
    built = run_with_heartbeat(
        [sys.executable, str(V4_ROOT / "build_v4.py"), str(V4_ROOT / "examples" / "hello_world.fk"), "-o", str(hello)],
        label="V4 hello world build command", timeout_seconds=180, memory_limit_mb=512,
    )
    if built.returncode != 0 or not hello.exists():
        raise RuntimeError(f"V4 hello world build failed:\n{built.stdout}{built.stderr}")
    executed = run_with_heartbeat([str(hello)], label="V4 hello world execute", timeout_seconds=10, memory_limit_mb=128)
    if executed.returncode != 0 or executed.stdout != expected_native_stdout("Hello, world!\n") or executed.stderr:
        raise RuntimeError("V4 build command hello world stdout/exit mismatch")
    for label, source_text, expected in (
        ("numeric_display", 'task main() -> int { say 42\n give back 0 }\n', "42\n"),
        ("owned_word_display", 'task main() -> int { pilot text = "owned now"\n say text\n give back 0 }\n', "owned now\n"),
    ):
        source = RUNTIME_BUILD_ROOT / f"llvm_{label}.fk"
        source.write_text(source_text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / (label + (".exe" if sys.platform == "win32" else ".native"))
        output.unlink(missing_ok=True)
        built = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(output)],
            label=f"V4 {label} build command", timeout_seconds=180, memory_limit_mb=512,
        )
        if built.returncode != 0 or not output.exists() or "v4-errors=0" not in built.stdout:
            raise RuntimeError(f"V4 {label} build failed:\n{built.stdout}{built.stderr}")
        executed = run_with_heartbeat([str(output)], label=f"V4 {label} execute",
                                      timeout_seconds=10, memory_limit_mb=128)
        if executed.returncode != 0 or executed.stdout != expected_native_stdout(expected) or executed.stderr:
            raise RuntimeError(f"V4 {label} stdout/exit mismatch:\n{executed.stdout}{executed.stderr}")
        print(f"V4 build command: {label} exact native output")
    # Tier 2 bootstrap root scope: root pilots become module globals and root
    # statements run in a module init before main (or alone, for a script).
    bootstrap_cases = (
        ("bootstrap_int_globals",
         'pilot counter = 5\npilot step: int = 2\npilot flag = false\ncounter += 1\n'
         'if counter > 5 {\n step = 3\n}\ntask bump() -> void {\n counter += step\n}\n'
         'task main() -> int {\n bump()\n if not flag {\n  flag = true\n  bump()\n }\n give back counter\n}\n',
         "", 12),
        ("bootstrap_word_globals",
         'pilot label = "hello"\npilot count = 0\nsay label\n'
         'task shout() -> void {\n label = label + "!"\n count += 1\n}\n'
         'task main() -> int {\n say label\n shout()\n shout()\n say label\n'
         ' pilot local = "from-" + "local"\n label = local\n say label\n say "count {count}"\n give back count\n}\n',
         "hello\nhello\nhello!!\nfrom-local\ncount 2\n", 2),
        ("bootstrap_script",
         'pilot greeting = "hi"\npilot n = 3\ntask twice(x: int) -> int { give back x * 2 }\n'
         'say greeting\nn = twice(n)\nrepeat until n <= 0 {\n say "n={n}"\n n -= 2\n}\nsay "done {greeting}"\n',
         "hi\nn=6\nn=4\nn=2\ndone hi\n", 0),
        # Bootstrap builtins: private array tickets, word_join (consumes its
        # ticket) and the snapshot word helpers. Braced calls stay literal.
        ("bootstrap_arrays",
         'pilot shared: int = array_new()\n'
         'task fill(list: int, count: int) -> void {\n'
         '    pilot i = 0\n'
         '    repeat until i >= count {\n'
         '        array_push(list, "item" + word_from_int(i))\n'
         '        i += 1\n'
         '    }\n'
         '}\n'
         'task main() -> int {\n'
         '    fill(shared, 3)\n'
         '    array_set(shared, 1, "middle")\n'
         '    say array_get(shared, 1)\n'
         '    pilot first = array_get(shared, 0)\n'
         '    say first\n'
         '    say "len {array_len(shared)}"\n'
         '    pilot payload = "a|b%c\\nsecond|x\\n"\n'
         '    pilot escaped = payload.snapshot_escape()\n'
         '    say escaped\n'
         '    say escaped.snapshot_unescape() == payload\n'
         '    say payload.snapshot_line_count()\n'
         '    pilot line = payload.snapshot_line(0)\n'
         '    say line.snapshot_field_count()\n'
         '    say line.snapshot_field_raw(1)\n'
         '    say payload.snapshot_line(9) == ""\n'
         '    pilot rows = payload.snapshot_lines()\n'
         '    say "rows {array_len(rows)}"\n'
         '    say array_get(rows, 1)\n'
         '    array_release(rows)\n'
         '    pilot parts = array_new()\n'
         '    array_push(parts, "x")\n'
         '    array_push(parts, first)\n'
         '    say word_join(parts)\n'
         '    give back array_len(shared)\n'
         '}\n'
         ,
         "middle\nitem0\nlen {array_len(shared)}\na%7Cb%25c%0Asecond%7Cx%0A\ntrue\n3\n2\nb%c\ntrue\nrows {array_len(rows)}\nsecond|x\nxitem0\n", 3),
        # V1 builtins the crates use: chr, word.checksum (V1's stable FNV-1a),
        # word_to_num, and V1-shaped process::arg / fs::read ("" on failure).
        # A "::" inside a string literal is not a route path.
        ("bootstrap_v1_builtins",
         'pilot sep = "::"\n'
         'task main() -> int {\n'
         '    say "a" + sep + "b" + "::" + "c"\n'
         '    say chr(65) + chr(233)\n'
         '    say chr(0).length()\n'
         '    say "abc".checksum()\n'
         '    say word_to_num("2.5") + 1.0\n'
         '    say process::arg(7) == ""\n'
         '    say fs::read("missing/v4-bootstrap-none.txt") == ""\n'
         '    pilot read = fs::read_checked("missing/v4-bootstrap-none.txt")\n'
         '    check result read {\n'
         '        ok(text) -> { say "read " + text }\n'
         '        err(error) -> { say "read-failed" }\n'
         '    }\n'
         '    give back 0\n'
         '}\n',
         "a::b::c\nA\u00e9\n1\n7430836138530658123\n3.5\ntrue\ntrue\nread-failed\n", 0),
        # A global initializer runs in the module init, so it may call an
        # ordinary task; a script may read process args; a root give back
        # ends the module init.
        ("bootstrap_global_task_init",
         'task make() -> int { give back 7 }\npilot count: int = make()\ntask main() -> int { give back count }\n', "", 7),
        ("bootstrap_script_args", 'pilot n: int = process::args_count()\nsay n\n', "1\n", 0),
        ("bootstrap_root_give_back", 'say "a"\ngive back\nsay "b"\n', "a\n", 0),
        # An unannotated global takes an ordinary task's return type, and a
        # bootstrap process::arg reads the real argv snapshot.
        # A root initializer's generic call shares the instance cache: the
        # drain runs after the module init is lowered.
        ("bootstrap_generic_root_init",
         'task ident<T>(x: T) -> T { give back x }\npilot n: int = ident(7)\ntask main() -> int { give back n }\n', "", 7),
        ("bootstrap_global_task_infer",
         'task make() -> int { give back 9 }\npilot n = make()\ntask main() -> int { give back n }\n', "", 9),
        ("bootstrap_process_arg_word", 'pilot self_path: word = process::arg(0)\nsay self_path != ""\n', "true\n", 0),
        # Bootstrap word reads share one refcounted handle, so changing a
        # copy must leave the original alone; char_at/substring keep V1's
        # lenient rules (out of range gives "", substring(start, count)
        # clamps), and length() counts scalars, not bytes; byte_length()
        # counts bytes (codegen sizes non-ASCII literals with it, so a
        # self-built compiler emits the same module as the Python-built one).
        ("bootstrap_word_share_v1_index",
         'pilot g: word = "ab"\n'
         'task main() -> int {\n'
         '    pilot a: word = "h\u00e9llo"\n'
         '    pilot mut b = a\n'
         '    b = b + "!"\n'
         '    pilot mut c = g\n'
         '    c = c + "c"\n'
         '    say a\n'
         '    say b\n'
         '    say g + " " + c\n'
         '    say a.char_at(1)\n'
         '    say a.char_at(99) == ""\n'
         '    say a.substring(3, 99)\n'
         '    say g.substring(5, 1) == ""\n'
         '    say a.byte_length()\n'
         '    give back a.length()\n'
         '}\n',
         "h\u00e9llo\nh\u00e9llo!\nab abc\n\u00e9\ntrue\nlo\ntrue\n6\n", 5),
    )
    for label, source_text, expected, expected_exit in bootstrap_cases:
        source = RUNTIME_BUILD_ROOT / f"llvm_{label}.fk"
        source.write_text(source_text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / (label + (".exe" if sys.platform == "win32" else ".native"))
        output.unlink(missing_ok=True)
        strict = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(output), "--emit-llvm"],
            label=f"V4 {label} strict build command", timeout_seconds=180, memory_limit_mb=512,
        )
        if strict.returncode == 0 or output.exists() or "v4-aborted-after=parse" not in strict.stdout + strict.stderr:
            raise RuntimeError(f"V4 {label} built without bootstrap mode:\n{strict.stdout}{strict.stderr}")
        built = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(output), "--bootstrap-root"],
            label=f"V4 {label} build command", timeout_seconds=180, memory_limit_mb=512,
        )
        if built.returncode != 0 or not output.exists() or "v4-errors=0" not in built.stdout:
            raise RuntimeError(f"V4 {label} build failed:\n{built.stdout}{built.stderr}")
        executed = run_with_heartbeat([str(output)], label=f"V4 {label} execute",
                                      timeout_seconds=10, memory_limit_mb=128)
        if executed.returncode != expected_exit or executed.stdout != expected_native_stdout(expected) or executed.stderr:
            raise RuntimeError(f"V4 {label} stdout/exit mismatch ({executed.returncode}):\n{executed.stdout}{executed.stderr}")
        print(f"V4 build command: {label} strict-rejected bootstrap-exact")
    # Multi-file build: sources flatten in the given order, and diagnostics
    # name the original file, line and column.
    multi_a = RUNTIME_BUILD_ROOT / "llvm_multi_a.fk"
    multi_b = RUNTIME_BUILD_ROOT / "llvm_multi_b.fk"
    multi_a.write_text('task helper() -> int { give back 2 }\n', encoding="utf-8")
    multi_output = RUNTIME_BUILD_ROOT / ("llvm_multi" + (".exe" if sys.platform == "win32" else ".native"))
    for broken in (True, False):
        multi_b.write_text('pilot base = 40\ntask main() -> int {\n give back base + helper()' + (' + missing' if broken else '') + '\n}\n', encoding="utf-8")
        multi_output.unlink(missing_ok=True)
        built = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(multi_a), str(multi_b), "-o", str(multi_output), "--bootstrap-root"],
            label="V4 multi-file build command", timeout_seconds=180, memory_limit_mb=512,
        )
        combined = built.stdout + built.stderr
        if broken:
            if built.returncode == 0 or multi_output.exists() or "unknown name: missing" not in combined or "llvm_multi_b.fk:3:30" not in combined:
                raise RuntimeError(f"V4 multi-file build did not map its diagnostic to the original file:\n{combined}")
            continue
        if built.returncode != 0 or not multi_output.exists() or "v4-flattened sources=2" not in built.stdout:
            raise RuntimeError(f"V4 multi-file build failed:\n{combined}")
        executed = run_with_heartbeat([str(multi_output)], label="V4 multi-file execute", timeout_seconds=10, memory_limit_mb=128)
        if executed.returncode != 42 or executed.stdout or executed.stderr:
            raise RuntimeError(f"V4 multi-file program exit mismatch ({executed.returncode})")
    print("V4 build command: multi-file flatten runs and maps diagnostics to file:line:col")
    strict_array_source = RUNTIME_BUILD_ROOT / "llvm_strict_array.fk"
    strict_array_source.write_text('task main() -> int {\n pilot parts = array_new()\n give back array_len(parts)\n}\n', encoding="utf-8")
    strict_array_output = RUNTIME_BUILD_ROOT / "llvm_strict_array.ll"
    strict_array_output.unlink(missing_ok=True)
    rejected = run_with_heartbeat(
        [sys.executable, str(V4_ROOT / "build_v4.py"), str(strict_array_source), "-o", str(strict_array_output), "--emit-llvm"],
        label="V4 strict array builtin build command", timeout_seconds=180, memory_limit_mb=512,
    )
    combined = rejected.stdout + rejected.stderr
    if rejected.returncode == 0 or strict_array_output.exists() or "array_new is a compiler builtin that exists only in bootstrap mode" not in combined:
        raise RuntimeError(f"V4 strict build admitted or misnamed a bootstrap builtin:\n{combined}")
    print("V4 build command: strict array builtin rejected with bootstrap hint")
    for label, source_text, reason, stage in (
        ("const_global", 'pilot counter = 5\nfixed pilot LIMIT: int = counter\ntask main() -> int { give back LIMIT }\n',
         "constant reads a runtime global", "ty"),
        ("shape_global", 'shape P { x: int }\npilot origin = P { x: 3 }\ntask main() -> int { give back origin.x }\n',
         "root pilot type is not supported yet", "mir"),
        ("root_local_annotation", 'if true {\n    pilot x: int = "text"\n    say x\n}\n',
         "local declaration type mismatch", "mir"),
        # An explicit lend of a word local loans the local itself (no
        # bootstrap copy), so MIR accepts it and only native codegen stops,
        # exactly as in strict mode.
        ("word_lend_local", 'task size(w: lend word) -> int { give back 4 }\ntask main() -> int {\n    pilot a: word = "abcd"\n    give back size(lend a)\n}\n',
         "native borrowed word local storage is not yet supported", "codegen"),
    ):
        source = RUNTIME_BUILD_ROOT / f"llvm_bootstrap_{label}.fk"
        source.write_text(source_text, encoding="utf-8")
        output = RUNTIME_BUILD_ROOT / f"llvm_bootstrap_{label}.ll"
        output.unlink(missing_ok=True)
        rejected = run_with_heartbeat(
            [sys.executable, str(V4_ROOT / "build_v4.py"), str(source), "-o", str(output), "--emit-llvm", "--bootstrap-root"],
            label=f"V4 bootstrap {label} build command", timeout_seconds=180, memory_limit_mb=512,
        )
        combined = rejected.stdout + rejected.stderr
        if rejected.returncode == 0 or output.exists() or reason not in combined or f"v4-aborted-after={stage}" not in combined:
            raise RuntimeError(f"V4 bootstrap {label} was not rejected by name at {stage}:\n{combined}")
        print(f"V4 build command: bootstrap {label} rejected at {stage}")
    print("V4 build command: hello world, numeric/owned-word display and warning-only execute, errors stop at their owning stage")


def smoke_execution_cases(smokes: list[dict[str, object]]):
    """Keep independent resource cases in separate guarded native processes."""
    for smoke in smokes:
        if "runtime_cases" not in smoke:
            yield smoke
            continue
        cases = smoke["runtime_cases"]
        if not isinstance(cases, list) or not cases:
            raise ValueError("runtime_cases must be a nonempty list")
        for index, case in enumerate(cases):
            if not isinstance(case, dict) or case.keys() - {"argv", "expect", "llvm_programs", "llvm_abort_messages"}:
                raise ValueError("runtime case may only select arguments and expected execution")
            expanded = {key: value for key, value in smoke.items() if key != "runtime_cases"}
            expanded.update(case)
            expanded["name"] = f"{smoke['name']} ({index + 1}/{len(cases)})"
            yield expanded


def check_executable_smokes(
    base_source: str,
    smokes: list[dict[str, object]],
) -> None:
    clang = shutil.which("clang")
    if clang is None:
        print("runtime smoke failed: clang not found")
        raise SystemExit(1)

    RUNTIME_BUILD_ROOT.mkdir(parents=True, exist_ok=True)
    runtime_c = RUNTIME_ROOT / "freak_runtime.c"
    runtime_smoke_c = RUNTIME_BUILD_ROOT / "freak_runtime_v4_smoke.c"
    runtime_source = read_text(runtime_c)
    write_text_if_changed(runtime_smoke_c, runtime_source)
    include_arg = f"-I{RUNTIME_ROOT}"
    check_process_tree_guard()
    check_llvm_runtime_primitives(clang, include_arg)
    check_checked_source_runtime(clang)
    check_native_snapshot_lines(clang)
    check_v3_llvm_substring_pipeline(clang, include_arg)

    # Expanded runtime cases of one smoke share its fixture, and the
    # transpile is a pure function of (crates, fixture). Reuse the previous
    # fixture's C instead of re-transpiling ~5 MB of C once per argv case.
    previous_fixture: Path | None = None
    previous_transpile: tuple[str, bool] | None = None
    for smoke in smoke_execution_cases(smokes):
        fixture = TESTS_ROOT / str(smoke["fixture"])
        label = rel(fixture)
        if fixture == previous_fixture and previous_transpile is not None:
            c_source, uses_ui = previous_transpile
            transpile_mode = "reused"
        else:
            previous_transpile = None
            c_source, uses_ui = transpile_fixture(base_source, fixture)
            previous_fixture = fixture
            previous_transpile = (c_source, uses_ui)
            transpile_mode = "fresh"
        print(f"fixture transpile: {label} c_bytes={len(c_source)} uses_ui={uses_ui} transpile={transpile_mode}")
        if uses_ui:
            print(f"runtime smoke failed: {label} unexpectedly requires UI")
            raise SystemExit(1)

        print(f"runtime smoke start: {smoke['name']} fixture={label}")
        extra_cflags: tuple[str, ...] = ()
        if fixture.name in C_ARRAY_HANDLE_RESOURCE_FIXTURES:
            extra_cflags = (
                f"-DFREAK_ARRAY_LIVE_LIMIT={C_ARRAY_HANDLE_RESOURCE_LIMIT}",
            )
        exe_path, compiled = compile_runtime_smoke(
            clang,
            include_arg,
            runtime_smoke_c,
            runtime_source,
            fixture,
            c_source,
            extra_cflags,
        )
        timeout_seconds = int(smoke.get("timeout", 60))
        default_memory_limit_mb = 128 if "snapshot" in fixture.stem else 512
        command = [str(exe_path)]
        command += smoke.get("argv", [])
        if smoke.get("source_read_checks"):
            command += checked_source_fixture_paths()
        if smoke.get("llvm_programs"):
            from build_v4 import host_target
            command += [str(V4_ROOT / "examples" / name) for name, _, _ in smoke["llvm_programs"]]
            command.append(host_target())
        executed = run_with_heartbeat(
            command,
            label=f"runtime execute: {label}",
            timeout_seconds=timeout_seconds,
            memory_limit_mb=int(smoke.get("memory_limit_mb", default_memory_limit_mb)),
        )
        output = executed.stdout + executed.stderr
        if executed.returncode != 0:
            print(f"runtime execution failed: {label} exit={executed.returncode}")
            print(output[:4000])
            raise SystemExit(1)

        if smoke.get("expect_stderr_empty") and executed.stderr:
            print(f"runtime smoke failed: {label} unexpected stderr")
            print(executed.stderr[:4000])
            raise SystemExit(1)

        output_lines = output.splitlines()
        output_line_counts = Counter(output_lines)
        if smoke.get("expect_mode") == "line":
            missing = [needle for needle in smoke["expect"] if needle not in output_lines]
        else:
            missing = [needle for needle in smoke["expect"] if needle not in output]
        missing_exact = [line for line in smoke.get("expect_exact", []) if line not in output_lines]
        missing.extend(missing_exact)
        unique_failures: list[tuple[str, int, int, int | None]] = []
        if smoke.get("expect_unique"):
            registered_lines = [*smoke["expect"], *smoke.get("expect_exact", [])]
            unique_failures = unique_output_failures(
                registered_lines, output_line_counts
            )
        if missing or unique_failures:
            print(f"runtime smoke failed: {label}")
            for needle in missing:
                print(f"missing output: {needle}")
            for line, registered_count, output_count, keyed_output_count in unique_failures:
                keyed_detail = (
                    ""
                    if keyed_output_count is None
                    else f" keyed_emitted={keyed_output_count}"
                )
                print(
                    "non-unique output: "
                    f"registered={registered_count} emitted={output_count}"
                    f"{keyed_detail} line={line}"
                )
            print(output[:4000])
            raise SystemExit(1)

        if smoke.get("llvm_programs"):
            modules = extract_llvm_modules(output)
            if len(modules) != len(smoke["llvm_programs"]):
                raise RuntimeError("LLVM module smoke emitted the wrong number of modules")
            for (name, exit_code, stdout), module in zip(smoke["llvm_programs"], modules, strict=True):
                llvm_text_floor_module().require_text_floor(module, f"LLVM module smoke: {name}")
                ll_path = RUNTIME_BUILD_ROOT / f"{Path(name).stem}.v4.ll"
                native_path = ll_path.with_suffix(".exe" if sys.platform == "win32" else ".native")
                ll_path.write_bytes(module.encode("utf-8"))
                linked = run_with_heartbeat(
                    [clang, "-w", "-O2", str(ll_path),
                     *(str(RUNTIME_ROOT / source) for source in V4_NATIVE_RUNTIME_SOURCES),
                     include_arg, "-o", str(native_path),
                     *runtime_platform_final_link_args()],
                    label=f"LLVM module link: {name}", timeout_seconds=120, memory_limit_mb=512,
                )
                if linked.returncode != 0:
                    raise RuntimeError(f"LLVM module link failed: {name}\n{linked.stdout}{linked.stderr}")
                native = run_with_heartbeat(
                    [str(native_path)], label=f"LLVM module execute: {name}",
                    timeout_seconds=10, memory_limit_mb=128,
                )
                abort_message = smoke.get("llvm_abort_messages", {}).get(name)
                if abort_message is not None:
                    from tests.v4_panic_runtime import assert_exact_abort
                    byte_result = subprocess.CompletedProcess(
                        native.args, native.returncode, native.stdout.encode("utf-8"), native.stderr.encode("utf-8"))
                    assert_exact_abort(byte_result, ("PANIC: " + abort_message + "\n").encode("utf-8"))
                elif native.returncode != exit_code or native.stdout != expected_native_stdout(stdout) or native.stderr:
                    raise RuntimeError(f"LLVM module execution failed: {name} expected={exit_code} actual={native.returncode}\n{native.stdout}{native.stderr}")
                print(f"LLVM module execution: {name} exit={exit_code}")
        if smoke.get("llvm_build_checks"):
            check_v4_build_command()

        compile_mode = "clang" if compiled else "cache"
        print(
            f"runtime smoke: {smoke['name']} fixture={label} "
            f"compile={compile_mode} output_bytes={len(output)}"
        )
        del c_source
        del executed
        del output
        del output_lines
        del output_line_counts
        check_runner_retained_memory()


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Run Maverick (00-unit) V4 bootstrap checks.")
    parser.add_argument(
        "--fast",
        action="store_true",
        help="skip executable runtime smokes and stop after fixture transpiles",
    )
    parser.add_argument(
        "--smoke",
        action="append",
        default=[],
        metavar="NAME",
        help="run only matching executable smoke fixtures by name or fixture stem",
    )
    parser.add_argument(
        "--smoke-shard",
        default="",
        metavar="INDEX/TOTAL",
        help="run one deterministic shard of the selected executable smokes",
    )
    parser.add_argument(
        "--smoke-exclude",
        action="append",
        default=[],
        metavar="NAME",
        help="exclude matching executable smokes before sharding",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    global RUNNER_PEAK_RETAINED_BYTES
    RUNNER_PEAK_RETAINED_BYTES = 0
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(line_buffering=True)
    if hasattr(sys.stderr, "reconfigure"):
        sys.stderr.reconfigure(line_buffering=True)
    args = parse_args(argv)
    check_runtime_platform_link_contract()
    check_process_memory_sampler()
    crates = crate_paths()
    fixtures = fixture_paths()
    all_files = crates + fixtures + [V4_ROOT / "README.md"]
    selected_smokes = select_smokes(args.smoke, args.smoke_exclude, args.smoke_shard)
    selected_fixture_set = {TESTS_ROOT / str(smoke["fixture"]) for smoke in selected_smokes}
    transpile_targets = fixtures if not (args.smoke or args.smoke_exclude or args.smoke_shard) else [fixture for fixture in fixtures if fixture in selected_fixture_set]

    print("Maverick (00-unit) checks")
    check_exists(crates)
    check_ascii(all_files)
    check_individual_parse(crates + fixtures)
    check_smoke_inventory(fixtures)
    check_crate_boundaries()
    check_alias_hir_boundary()
    check_mir_local_annotation_boundary()
    check_task_return_hir_boundary()
    check_task_param_hir_boundary()
    check_shape_field_hir_boundary()
    check_const_hir_boundary()
    check_route_hir_boundary()
    check_extern_return_hir_boundary()
    check_tooling_interfaces()
    check_snapshot_inventories()
    check_llvm_text_floor()
    base_source = check_flattened_crates()
    if args.fast and (args.smoke or args.smoke_exclude or args.smoke_shard):
        mode_bits: list[str] = [f"fixtures={len(transpile_targets)}"]
        if args.smoke:
            mode_bits.append(f"filters={len(args.smoke)}")
        if args.smoke_exclude:
            mode_bits.append(f"excludes={len(args.smoke_exclude)}")
        if args.smoke_shard:
            mode_bits.append(f"shard={args.smoke_shard}")
        print("mode: fast " + " ".join(mode_bits))
    elif args.fast:
        print("mode: fast")
    elif args.smoke or args.smoke_exclude or args.smoke_shard:
        mode_bits = [f"smokes={len(selected_smokes)}"]
        if args.smoke_exclude:
            mode_bits.append(f"excludes={len(args.smoke_exclude)}")
        if args.smoke_shard:
            mode_bits.append(f"shard={args.smoke_shard}")
        print("mode: targeted " + " ".join(mode_bits))

    if args.fast:
        check_fixture_transpile(base_source, transpile_targets)
    else:
        runtime_targets = {TESTS_ROOT / str(smoke["fixture"]) for smoke in selected_smokes}
        check_fixture_transpile(
            base_source,
            [fixture for fixture in transpile_targets if fixture not in runtime_targets],
        )
        check_executable_smokes(base_source, selected_smokes)
    check_runner_retained_memory()
    if RUNNER_PEAK_RETAINED_BYTES > 0:
        print(
            "runner memory: "
            f"peak-retained={RUNNER_PEAK_RETAINED_BYTES / (1024 * 1024):.1f}MB "
            f"limit={RUNNER_RETAINED_MEMORY_LIMIT_MB}MB"
        )
    print("Maverick checks passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
